const QUESTIONS = [
  { id: "q0001", topic: "communication:general", level: "A2", difficulty: 4, type: "tiles", q: "Составь:\n«Я участвую в курсе.»", rule: "r0020", words: ["Ich", "nehme", "an", "dem", "Kurs", "teil."], explain: "teilnehmen – отдел. teil- уходит в конец. teilnehmen an + Dat." },
  { id: "q0002", topic: "communication:general", level: "A2", difficulty: 4, type: "tiles", q: "Составь:\n«Это предложение очень выгодное.»", words: ["Das", "Angebot", "ist", "sehr", "günstig."], explain: "После sein – без окончания. das Angebot (n)." },
  { id: "q0003", topic: "communication:greetings", level: "A2", difficulty: 4, type: "tiles", q: "Составь:\n«Сердечно приветствуем в Берлине!»", words: ["Herzlich", "willkommen", "in", "Berlin!"], explain: "Стандартная формула приветствия. in + Dat (im/in Berlin)." },
  { id: "q0004", topic: "grammar:cases", level: "A2", difficulty: 2, type: "fill", q: "Pl от \"der Gruß\"?", ans: "die Grüße", altAns: ["Grüße"], hint: "+ Umlaut, +e", explain: "der Gruß → die Grüße (u→ü, +e)." },
  { id: "q0005", topic: "grammar:articles", level: "A2", difficulty: 2, type: "fill", q: "Какой артикль? \"___ Kunst\"", rule: "r0013", ans: "die", hint: "женский род", explain: "die Kunst (f). Pl: die Künste." },
  { id: "q0006", topic: "grammar:articles", level: "A2", difficulty: 2, type: "fill", q: "Какой артикль? \"___ Angebot\" (предложение)", rule: "r0013", ans: "das", hint: "средний род", explain: "das Angebot (n). От anbieten." },
  { id: "q0007", topic: "grammar:articles", level: "A2", difficulty: 1, type: "fill", q: "От какого слова образовано «herzlich»?", ans: "Herz", altAns: ["das Herz", "Herz"], hint: "сердце", explain: "Herz + -lich = herzlich. Суффикс -lich образует прилагательные." },
  { id: "q0008", topic: "grammar:articles", level: "A2", difficulty: 1, type: "fill", q: "От какого слова «täglich»?", ans: "Tag", altAns: ["der Tag", "Tag"], hint: "день", explain: "Tag + -lich = täglich (с умлаутом)." },
  { id: "q0009", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «laden» в Präsens:", rule: "r0009", ans: ["lade", "lädst", "lädt", "laden", "ladet", "laden"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "Unregelmäßig: a→ä у du и er. ich lade, du lädst, er lädt." },
  { id: "q0010", topic: "quantity:cardinal", level: "A1", difficulty: 2, type: "mc", q: "Как пишется число 30?", opts: ["dreizig", "dreißig", "dreizehn", "drießig"], ans: 1, explain: "30 – dreißig. Через ß, не z." },
  { id: "q0011", topic: "quantity:cardinal", level: "A1", difficulty: 1, type: "mc", q: "Что означает «halb drei»?", opts: ["3 часа", "2:30", "3:30", "половина четвёртого"], ans: 1, explain: "halb drei = половина третьего = 2:30. В немецком смотрят на СЛЕДУЮЩИЙ час." },
  { id: "q0012", topic: "quantity:cardinal", level: "A1", difficulty: 2, type: "mc", q: "Какой предлог для дней?", rule: "r0034", opts: ["um", "in", "am", "auf"], ans: 2, explain: "am Montag, am Dienstag... am = an + dem (Dativ)." },
  { id: "q0013", topic: "quantity:cardinal", level: "A1", difficulty: 2, type: "mc", q: "Какой предлог для времени (часов)?", rule: "r0034", opts: ["am", "um", "in", "bei"], ans: 1, explain: "um 5 Uhr – в 5 часов." },
  { id: "q0014", topic: "quantity:cardinal", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «В понедельник в 5 часов.»", rule: "r0034", words: ["Am", "Montag", "um", "5", "Uhr."], explain: "am + день, um + время." },
  { id: "q0015", topic: "quantity:cardinal", level: "A2", difficulty: 3, type: "fill", q: "Вставь: \"Es ist ___ drei.\" (2:30)", ans: "halb", hint: "половина", explain: "halb drei = 2:30. На следующий час." },
  { id: "q0016", topic: "quantity:cardinal", level: "A2", difficulty: 3, type: "fill", q: "Вставь: \"viertel ___ zwölf\" (12:15)", ans: "nach", hint: "после полудня", explain: "viertel nach zwölf = четверть первого = 12:15." },
  { id: "q0017", topic: "phonetics:rules", level: "A1", difficulty: 1, type: "mc", q: "Как читается «ei» в слове «mein»?", opts: ["[эй]", "[ай]", "[и]", "[е]"], ans: 1, explain: "ei, ai → [ай]. mein = [майн]." },
  { id: "q0018", topic: "phonetics:rules", level: "A1", difficulty: 1, type: "mc", q: "Как читается «ie» в слове «sieben»?", opts: ["[ие]", "[й]", "[и:]", "[ай]"], ans: 2, explain: "ie → [и:] (долгое и). sieben = [зибэн]." },
  { id: "q0019", topic: "phonetics:rules", level: "A1", difficulty: 1, type: "mc", q: "Как читается «eu» в слове «neun»?", opts: ["[еу]", "[э]", "[ой]", "[у]"], ans: 2, explain: "eu, äu → [ой]. neun = [нойн]." },
  { id: "q0020", topic: "phonetics:rules", level: "A1", difficulty: 1, type: "mc", q: "Как читается «sch» в «Schule»?", opts: ["[сч]", "[ш]", "[ск]", "[щ]"], ans: 1, explain: "sch → [ш]. Schule = [шулэ]." },
  { id: "q0021", topic: "phonetics:rules", level: "A1", difficulty: 1, type: "mc", q: "Как читается «ch» в слове «ich»?", opts: ["[х] – ach-Laut", "[к]", "[хь] – ich-Laut", "[ш]"], ans: 2, explain: "ch после e/i/ei/ä/ö/ü → [хь] (ich-Laut). ich = [ихь]." },
  { id: "q0022", topic: "phonetics:rules", level: "A1", difficulty: 1, type: "mc", q: "Как читается «ch» в слове «machen»?", opts: ["[хь]", "[к]", "[х] – ach-Laut", "[ш]"], ans: 2, explain: "ch после a/o/u/au → [х] (ach-Laut). machen = [махэн]." },
  { id: "q0023", topic: "grammar:verbs", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Ты любишь готовить?»", rule: "r0016", words: ["Kochst", "du", "gern?"], explain: "Verb + gern = «любить (делать)». Ja/Nein-Frage: Verb на 1-й позиции." },
  { id: "q0024", topic: "grammar:verbs", level: "A2", difficulty: 2, type: "fill", q: "Präteritum от «sein» для «ich»?", rule: "r0005", ans: "war", hint: "был", explain: "ich war (Präteritum)." },
  { id: "q0025", topic: "grammar:verbs", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Я не могу прийти.»", rule: "r0008", words: ["Ich", "kann", "nicht", "kommen."], explain: "Modalverb на 2-й позиции, Infinitiv в конец." },
  { id: "q0026", topic: "grammar:verbs", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Я хочу учить немецкий.»", rule: "r0008", words: ["Ich", "will", "Deutsch", "lernen."], explain: "wollen на 2-й позиции, Infinitiv (lernen) в конце." },
  { id: "q0027", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "fill", q: "Вставь: \"Ich ___ Deutsch lernen.\" (хочу)", rule: "r0008", ans: "will", hint: "wollen – ich", explain: "ich will. Modalverb." },
  { id: "q0028", topic: "grammar:modal", level: "A2", difficulty: 3, type: "fill", q: "sollen или müssen?\n\"Ich ___ schlafen.\" (сам устал)", rule: "r0018", ans: "muss", hint: "обязательство изнутри", explain: "müssen – обязательство ИЗНУТРИ / объективная необходимость." },
  { id: "q0029", topic: "grammar:modal", level: "A2", difficulty: 3, type: "fill", q: "sollen или müssen?\n\"Du ___ nicht lügen.\" (тебе говорят)", rule: "r0018", ans: "sollst", hint: "обязательство извне", explain: "sollen – обязательство ИЗВНЕ. Du sollst nicht lügen." },
  { id: "q0030", topic: "grammar:modal", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «können» в Präsens:", rule: "r0035", ans: ["kann", "kannst", "kann", "können", "könnt", "können"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "ich = er (kann). Modalverb." },
  { id: "q0031", topic: "grammar:modal", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «wollen» в Präsens:", rule: "r0035", ans: ["will", "willst", "will", "wollen", "wollt", "wollen"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "ich = er (will)." },
  { id: "q0032", topic: "grammar:modal", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «müssen» в Präsens:", rule: "r0035", ans: ["muss", "musst", "muss", "müssen", "müsst", "müssen"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "ich = er (muss)." },
  { id: "q0033", topic: "grammar:modal", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «dürfen» в Präsens:", rule: "r0035", ans: ["darf", "darfst", "darf", "dürfen", "dürft", "dürfen"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "ich = er (darf)." },
  { id: "q0034", topic: "grammar:verbs", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Я забираю тебя в 7 часов.»", rule: "r0020", words: ["Ich", "hole", "dich", "um", "7", "Uhr", "ab."], explain: "abholen – отделяемая. ab- уходит в конец." },
  { id: "q0035", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "fill", q: "Вставь: \"Er ___ Pizza.\" (есть)", rule: "r0009", ans: "isst", hint: "essen – er", explain: "essen → er isst (e→i)." },
  { id: "q0036", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "fill", q: "Вставь: \"Du ___ schnell.\" (брать)", rule: "r0009", ans: "nimmst", hint: "nehmen – du", explain: "nehmen → du nimmst (h уходит, e→i, m→mm)." },
  { id: "q0037", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "fill", q: "wissen или kennen? \"Ich ___ ihn gut.\" (его)", rule: "r0006", ans: "kenne", hint: "знать человека", explain: "kennen – знать человека. wissen – знать факт." },
  { id: "q0038", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "fill", q: "wissen или kennen? \"Ich ___, wo er wohnt.\"", rule: "r0006", ans: "weiß", hint: "знать факт", explain: "wissen – знать факт. Unregel: ich weiß." },
  { id: "q0039", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "fill", q: "vermissen или verlieren?\n\"Ich ___ meinen Schlüssel.\" (потерял)", ans: "verliere", altAns: ["habe verloren"], hint: "о предмете", explain: "verlieren – терять (предмет). vermissen – скучать." },
  { id: "q0040", topic: "grammar:cases", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Я работаю в офисе.»", rule: "r0031", words: ["Ich", "arbeite", "im", "Büro."], explain: "im = in + dem (Dat). Wo? – Dativ." },
  { id: "q0041", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «sein» в Präsens:", rule: "r0009", ans: ["bin", "bist", "ist", "sind", "seid", "sind"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "Самый неправильный глагол. Учи наизусть." },
  { id: "q0042", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «haben» в Präsens:", rule: "r0009", ans: ["habe", "hast", "hat", "haben", "habt", "haben"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "du hast / er hat – без b!" },
  { id: "q0043", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «nehmen» в Präsens:", rule: "r0009", ans: ["nehme", "nimmst", "nimmt", "nehmen", "nehmt", "nehmen"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "du/er: nimm- (h уходит, e→i)." },
  { id: "q0044", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «sprechen» в Präsens:", rule: "r0009", ans: ["spreche", "sprichst", "spricht", "sprechen", "sprecht", "sprechen"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "e→i в du/er." },
  { id: "q0045", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «schlafen» в Präsens:", rule: "r0009", ans: ["schlafe", "schläfst", "schläft", "schlafen", "schlaft", "schlafen"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "a→ä в du/er." },
  { id: "q0046", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «sehen» в Präsens:", rule: "r0009", ans: ["sehe", "siehst", "sieht", "sehen", "seht", "sehen"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "e→ie в du/er. siehst, sieht." },
  { id: "q0047", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «essen» в Präsens:", rule: "r0009", ans: ["esse", "isst", "isst", "essen", "esst", "essen"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "du/er совпадают: isst." },
  { id: "q0048", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «werfen» в Präsens:", rule: "r0009", ans: ["werfe", "wirfst", "wirft", "werfen", "werft", "werfen"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "e→i: du wirfst, er wirft." },
  { id: "q0049", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "conj", q: "Проспрягай «fangen» в Präsens:", rule: "r0009", ans: ["fange", "fängst", "fängt", "fangen", "fangt", "fangen"], pronouns: ["ich", "du", "er/sie/es", "wir", "ihr", "sie/Sie"], explain: "a→ä: du fängst, er fängt." },
  { id: "q0050", topic: "grammar:verbs", level: "A1", difficulty: 2, type: "mc", q: "Partizip II от «sehen»?", rule: "r0015", opts: ["geseht", "gesehen", "sehte", "sah"], ans: 1, explain: "sehen – Unregel. Part II: gesehen (с haben)." },
  { id: "q0051", topic: "grammar:verbs", level: "A1", difficulty: 2, type: "mc", q: "Präteritum от «bleiben»?", opts: ["bleibte", "blieb", "blei", "geblieben"], ans: 1, explain: "bleiben → blieb / geblieben (с sein)." },
  { id: "q0052", topic: "grammar:verbs", level: "A1", difficulty: 2, type: "mc", q: "Какое вспомогательное у «fliegen» в Perfekt?", rule: "r0022", opts: ["haben", "sein", "werden", "müssen"], ans: 1, explain: "Глаголы движения → sein. Ich bin geflogen." },
  { id: "q0053", topic: "grammar:cases", level: "A2", difficulty: 2, type: "fill", q: "Pl от \"das Kind\"?", ans: "die Kinder", altAns: ["Kinder"], hint: "+er", explain: "das Kind → die Kinder." },
  { id: "q0054", topic: "grammar:cases", level: "A2", difficulty: 2, type: "fill", q: "Pl от \"der Vater\"?", ans: "die Väter", altAns: ["Väter"], hint: "+ Umlaut", explain: "der Vater → die Väter (a→ä)." },
  { id: "q0055", topic: "grammar:cases", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Холодильник на кухне.»", rule: "r0031", words: ["Der", "Kühlschrank", "ist", "in", "der", "Küche."], explain: "Wo? + Dat. in der Küche (f, Dat)." },
  { id: "q0056", topic: "grammar:cases", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «У меня есть собака.»", words: ["Ich", "habe", "einen", "Hund."], explain: "haben + Akk. der Hund (m) → einen Hund." },
  { id: "q0057", topic: "grammar:articles", level: "A2", difficulty: 2, type: "fill", q: "Какой артикль? \"___ Küche\" (кухня)", rule: "r0013", ans: "die", hint: "женский род", explain: "die Küche (f)." },
  { id: "q0058", topic: "grammar:articles", level: "A2", difficulty: 2, type: "fill", q: "Какой артикль? \"___ Auto\" (машина)", rule: "r0013", ans: "das", hint: "средний род", explain: "das Auto (n)." },
  { id: "q0059", topic: "grammar:articles", level: "A2", difficulty: 2, type: "fill", q: "Какой артикль? \"___ Hund\" (собака)", rule: "r0013", ans: "der", hint: "мужской род", explain: "der Hund (m)." },
  { id: "q0060", topic: "grammar:adjectives", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Квартира маленькая, но красивая.»", words: ["Die", "Wohnung", "ist", "klein,", "aber", "schön."], explain: "После sein – без окончания. aber = но." },
  { id: "q0061", topic: "grammar:adjectives", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «У меня большая собака.»", words: ["Ich", "habe", "einen", "großen", "Hund."], explain: "m, Akk → einen + großen (m Akk → -en)." },
  { id: "q0062", topic: "grammar:adjectives", level: "A2", difficulty: 1, type: "fill", q: "Антоним к «groß»?", ans: "klein", hint: "противоположное", explain: "groß ↔ klein." },
  { id: "q0063", topic: "grammar:adjectives", level: "A2", difficulty: 1, type: "fill", q: "Антоним к «teuer»?", ans: "billig", altAns: ["günstig"], hint: "↔ дорогой", explain: "teuer ↔ billig / günstig." },
  { id: "q0064", topic: "grammar:adjectives", level: "A2", difficulty: 2, type: "fill", q: "Окончание: «ein groß___ Haus» (n, Nom)", rule: "r0019", ans: "es", hint: "n с ein → -es", explain: "ein großes Haus (n)." },
  { id: "q0065", topic: "grammar:adjectives", level: "A2", difficulty: 2, type: "fill", q: "Окончание: «die schön___ Frau» (f, Nom)", rule: "r0019", ans: "e", hint: "f с der → -e", explain: "die schöne Frau." },
  { id: "q0066", topic: "grammar:adjectives", level: "A1", difficulty: 1, type: "mc", q: "schön или schon – «красивый»?", opts: ["schon", "schön", "оба", "ни одно"], ans: 1, explain: "schön = красивый. schon = уже (наречие)." },
  { id: "q0067", topic: "grammar:particles", level: "A1", difficulty: 1, type: "mc", q: "Шкала частоты: что чаще всего?", opts: ["selten", "manchmal", "oft", "immer"], ans: 3, explain: "immer → oft → manchmal → selten → nie." },
  { id: "q0068", topic: "grammar:particles", level: "A1", difficulty: 1, type: "mc", q: "morgen или der Morgen – «завтра»?", opts: ["der Morgen", "morgen (со строчной)", "оба", "ни одно"], ans: 1, explain: "morgen (наречие) = завтра. Morgen (с заглавной, m) = утро." },
  { id: "q0069", topic: "grammar:wordorder", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Завтра я работаю.»", rule: "r0053", words: ["Morgen", "arbeite", "ich."], explain: "Наречие в начале → инверсия: Verb + Subjekt. Morgen со строчной (правда, в начале предложения с заглавной – но это просто 1-я буква)." },
  { id: "q0070", topic: "communication:greetings", level: "A2", difficulty: 3, type: "fill", q: "Вставь: \"Bis ___!\" (До скорого)", ans: "gleich", hint: "сейчас, тут же", explain: "Bis gleich! – До скорого / Скоро увидимся." },
  { id: "q0071", topic: "grammar:adjectives", level: "A2", difficulty: 1, type: "fill", q: "Антоним «schnell»?", ans: "langsam", hint: "противоположное", explain: "schnell ↔ langsam." },
  { id: "q0072", topic: "grammar:pronouns", level: "A1", difficulty: 2, type: "mc", q: "Akkusativ от «ich»?", rule: "r0001", opts: ["mir", "mich", "mein", "ich"], ans: 1, explain: "ich → mich (Akk) / mir (Dat)." },
  { id: "q0073", topic: "grammar:pronouns", level: "A1", difficulty: 2, type: "mc", q: "Dativ от «du»?", rule: "r0001", opts: ["dich", "dein", "dir", "du"], ans: 2, explain: "du → dich (Akk) / dir (Dat)." },
  { id: "q0074", topic: "grammar:pronouns", level: "A1", difficulty: 2, type: "mc", q: "Dativ от «er»?", rule: "r0001", opts: ["ihn", "ihm", "ihr", "ihnen"], ans: 1, explain: "er → ihn (Akk) / ihm (Dat)." },
  { id: "q0075", topic: "grammar:pronouns", level: "A1", difficulty: 2, type: "mc", q: "Dativ от «es»?", rule: "r0001", opts: ["es", "ihm", "ihr", "ihnen"], ans: 1, explain: "⚠ es в Dat → ihm, не ihr! Ловушка." },
  { id: "q0076", topic: "grammar:pronouns", level: "A1", difficulty: 2, type: "mc", q: "Dativ от «sie» (она)?", rule: "r0001", opts: ["sie", "ihn", "ihm", "ihr"], ans: 3, explain: "sie (она) → sie (Akk) / ihr (Dat)." },
  { id: "q0077", topic: "grammar:pronouns", level: "A1", difficulty: 2, type: "mc", q: "«mein» или «meine» с «Wohnung» (f)?", opts: ["mein", "meine", "meinen", "meinem"], ans: 1, explain: "f → +e: meine Wohnung." },
  { id: "q0078", topic: "grammar:pronouns", level: "A1", difficulty: 2, type: "mc", q: "«mein» или «meine» с «Buch» (n)?", opts: ["mein", "meine", "meinen", "meinem"], ans: 0, explain: "n → без окончания: mein Buch." },
  { id: "q0079", topic: "grammar:pronouns", level: "A2", difficulty: 3, type: "fill", q: "Вставь: \"Ich wasche ___\" (моюсь)", rule: "r0002", ans: "mich", hint: "себя, Akk", explain: "ich → mich. Akkusativ – действие на себя." },
  { id: "q0080", topic: "grammar:pronouns", level: "A2", difficulty: 3, type: "fill", q: "Вставь: \"Ich wasche ___ die Hände\" (себе руки)", rule: "r0002", ans: "mir", hint: "себе, Dat", explain: "ich → mir. Dativ – кому?" },
  { id: "q0081", topic: "grammar:pronouns", level: "A2", difficulty: 2, type: "fill", q: "Возвратное для er/sie/es в Akk?", rule: "r0002", ans: "sich", hint: "всегда одно слово", explain: "Er/sie/es и sie/Sie → всегда sich." },
  { id: "q0082", topic: "grammar:cases", level: "A1", difficulty: 1, type: "mc", q: "Какой вопрос для Akkusativ?", rule: "r0024", opts: ["Wer?", "Wem?", "Wen?", "Wo?"], ans: 2, explain: "Akk → Wen? Was?" },
  { id: "q0083", topic: "grammar:cases", level: "A1", difficulty: 1, type: "mc", q: "Какой вопрос для Dativ?", rule: "r0024", opts: ["Wer?", "Wem?", "Wen?", "Wo?"], ans: 1, explain: "Dat → Wem?" },
  { id: "q0084", topic: "grammar:cases", level: "A1", difficulty: 1, type: "mc", q: "«Wohin?» спрашивает о...", rule: "r0017", opts: ["месте (где?)", "направлении (куда?)", "источнике (откуда?)", "времени"], ans: 1, explain: "Wohin? = куда? (направление, + Akk)." },
  { id: "q0085", topic: "grammar:cases", level: "A1", difficulty: 1, type: "mc", q: "«Wo?» использует какой падеж с предлогом?", rule: "r0031", opts: ["Nom", "Akk", "Dat", "никакой"], ans: 2, explain: "Wo? – статика → Dativ. Im, in der и т.д." },
  { id: "q0086", topic: "grammar:verbs", level: "A1", difficulty: 1, type: "mc", q: "«Ich bin ___» – что лучше подставить?", opts: ["Hunger", "müde", "Auto", "Buch"], ans: 1, explain: "sein + прил. → müde. haben + сущ. → Hunger." },
  { id: "q0087", topic: "grammar:verbs", level: "A1", difficulty: 2, type: "mc", q: "Partizip II от «besuchen»?", rule: "r0015", opts: ["gebesucht", "besucht", "besuchte", "besuchen"], ans: 1, explain: "Глаголы с be-/er-/ver- → БЕЗ ge-." },
  { id: "q0088", topic: "grammar:verbs", level: "A1", difficulty: 2, type: "mc", q: "Partizip II от «organisieren»?", rule: "r0015", opts: ["georganisiert", "organisiert", "organisierte", "organisieren"], ans: 1, explain: "Глаголы на -ieren → БЕЗ ge-." },
  { id: "q0089", topic: "grammar:verbs", level: "A1", difficulty: 2, type: "mc", q: "Partizip II от «machen»?", rule: "r0015", opts: ["machte", "gemacht", "macht", "gemächt"], ans: 1, explain: "Регулярный: ge- + основа + -t." },
  { id: "q0090", topic: "grammar:modal", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Здесь нельзя курить.»", rule: "r0003", words: ["Man", "darf", "hier", "nicht", "rauchen."], explain: "Modalverb на 2-й, Infinitiv в конец. nicht – отрицание действия." },
  { id: "q0091", topic: "grammar:verbs", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Я встаю в 7.»", rule: "r0020", words: ["Ich", "stehe", "um", "7", "Uhr", "auf."], explain: "aufstehen – отделяемая. auf уходит в конец." },
  { id: "q0092", topic: "grammar:verbs", level: "A2", difficulty: 2, type: "fill", q: "Präteritum от «haben» для «ich»?", rule: "r0005", ans: "hatte", hint: "имел", explain: "ich hatte." },
  { id: "q0093", topic: "grammar:cases", level: "A1", difficulty: 2, type: "fill", q: "Артикль в Akk от «der Hund»?", rule: "r0028", ans: "den", hint: "m → меняется", explain: "der → den (только m меняется в Akk)." },
  { id: "q0094", topic: "grammar:cases", level: "A1", difficulty: 2, type: "fill", q: "Артикль в Dat от «die Frau»?", rule: "r0028", ans: "der", hint: "f, Dat", explain: "f, Dat → der. Совпадает по форме с Nom m, но это Dat f." },
  { id: "q0095", topic: "communication:greetings", level: "A1", difficulty: 1, type: "mc", q: "«Wie geht es Ihnen?» – как ответить хорошо?", opts: ["Sehr gut, danke", "Auf Wiedersehen", "Gesundheit", "Wie bitte?"], ans: 0, explain: "Sehr gut, danke. Und Ihnen?" },
  { id: "q0096", topic: "communication:greetings", level: "A1", difficulty: 1, type: "mc", q: "Что значит «Tut mir leid»?", opts: ["Удачи!", "Мне жаль", "Очень приятно", "Что-нибудь ещё?"], ans: 1, explain: "Tut mir leid – мне жаль / прости." },
  { id: "q0097", topic: "communication:greetings", level: "A1", difficulty: 1, type: "mc", q: "Как сказать «Я голоден»?", opts: ["Ich bin Hunger", "Ich habe Hunger", "Mir ist Hunger", "Ich Hunger habe"], ans: 1, explain: "haben + Hunger (не sein!)." },
  { id: "q0098", topic: "communication:general", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Я бы хотел кофе.»", words: ["Ich", "hätte", "gern", "einen", "Kaffee."], explain: "hätte gern – вежливый заказ. der Kaffee (m) → einen." },
  { id: "q0099", topic: "communication:general", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Счёт, пожалуйста.»", words: ["Die", "Rechnung,", "bitte."], explain: "Die Rechnung, bitte. = Zahlen bitte." },
  { id: "q0100", topic: "grammar:pronouns", level: "A1", difficulty: 2, type: "mc", q: "Das Kind weint. Ich helfe ___ .", rule: "r0001", opts: ["ihr", "ihm", "es", "ihn"], ans: 1, explain: "helfen требует Dativ. Das Kind – n, значит es, а es в Dativ даёт ihm – как у er. Форма ihr принадлежит sie (она)." },
  { id: "q0101", topic: "grammar:pronouns", level: "A1", difficulty: 2, type: "mc", q: "«Я даю ей книгу.» Какое местоимение?", rule: "r0001", opts: ["sie", "ihr", "ihnen", "euch"], ans: 1, explain: "ihr = «ей», Dativ от sie (она). То же слово ihr значит «вы» в Nominativ – различает позиция в предложении." },
  { id: "q0102", topic: "grammar:pronouns", level: "A1", difficulty: 3, type: "mc", q: "Ich sehe ___ . (er)", rule: "r0001", opts: ["ihm", "er", "ihn", "ihr"], ans: 2, explain: "sehen требует Akkusativ → ihn. ihm – это Dativ, он пошёл бы после helfen или danken." },
  { id: "q0103", topic: "grammar:pronouns", level: "A1", difficulty: 3, type: "fill", q: "Вставь: «Der Lehrer dankt ___ .» (wir)", rule: "r0001", ans: "uns", hint: "danken + Dativ", explain: "danken требует Dativ, но у wir форма одна на Akkusativ и Dativ – uns. Падеж всё равно Dativ." },
  { id: "q0104", topic: "grammar:pronouns", level: "A1", difficulty: 4, type: "tiles", q: "Составь: «Я показываю тебе дорогу.»", rule: "r0001", words: ["Ich", "zeige", "dir", "den", "Weg."], explain: "zeigen берёт два дополнения: кому (Dativ, dir) и что (Akkusativ, den Weg). Dativ идёт первым." },
  { id: "q0105", topic: "grammar:pronouns", level: "A1", difficulty: 4, type: "tiles", q: "Составь: «Он объясняет мне задание.»", rule: "r0001", words: ["Er", "erklärt", "mir", "die", "Aufgabe."], explain: "erklären – тоже два дополнения. mir (Dativ) перед die Aufgabe (Akkusativ)." },
  { id: "q0106", topic: "grammar:pronouns", level: "A1", difficulty: 5, type: "open", q: "Переведи: «Я благодарю тебя.»", rule: "r0001", ans: "Ich danke dir.", altAns: ["Ich danke dir"], hint: "danken + Dativ", explain: "Ловушка: по-русски «благодарю кого?» – винительный, а danken требует Dativ. du → dir, не dich." },
  { id: "q0107", topic: "grammar:pronouns", level: "A1", difficulty: 5, type: "open", q: "Переведи: «Это нравится мне.»", rule: "r0001", ans: "Das gefällt mir.", altAns: ["Das gefällt mir", "Es gefällt mir"], hint: "gefallen + Dativ", explain: "gefallen требует Dativ: нравится КОМУ. ich → mir." },
  { id: "q0108", topic: "grammar:wordorder", level: "A2", difficulty: 3, type: "fill", q: "Вставь союз: «Ich bleibe zu Hause, ___ ich bin krank.»", rule: "r0053", ans: "denn", altAns: ["denn", "Denn"], hint: "обычный порядок слов после запятой", explain: "После запятой идёт ich, потом bin – глагол на второй позиции, обычный порядок. Так бывает только после сочинительного союза, который сам стоит на позиции 0. weil потребовал бы «weil ich krank bin»." },
  { id: "q0109", topic: "grammar:wordorder", level: "A2", difficulty: 3, type: "fill", q: "Вставь союз: «Ich bleibe zu Hause, ___ ich krank bin.»", rule: "r0053", ans: "weil", altAns: ["weil", "Weil", "da", "Da"], hint: "глагол уехал в конец", explain: "Глагол bin стоит последним – значит это Nebensatz. Отправить его туда мог только подчинительный союз: weil (или da в том же значении)." },
  { id: "q0110", topic: "grammar:wordorder", level: "A2", difficulty: 4, type: "tiles", q: "Составь второе предложение: «Идёт дождь. Поэтому я остаюсь дома.»", rule: "r0053", words: ["Deshalb", "bleibe", "ich", "zu", "Hause."], explain: "deshalb – наречие, оно само занимает позицию 1. Глагол обязан остаться на позиции 2, поэтому подлежащее ich съезжает за него. «Deshalb ich bleibe» – ошибка: там глагол оказывается третьим." },
  { id: "q0111", topic: "grammar:wordorder", level: "A2", difficulty: 3, type: "mc", q: "Он много работал. Несмотря на это он не устал. Какой вариант верный?", rule: "r0053", opts: ["Trotzdem er ist nicht müde.", "Trotzdem ist er nicht müde.", "Trotzdem er nicht müde ist.", "Er trotzdem ist nicht müde."], ans: 1, explain: "trotzdem работает как deshalb: это наречие на позиции 1, глагол ist держится за позицию 2, а подлежащее er уходит вправо. Вариант с «er nicht müde ist» – порядок придаточного, но trotzdem придаточное не вводит." },
  { id: "q0112", topic: "grammar:wordorder", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Хотя идёт дождь, мы идём гулять.»", rule: "r0053", words: ["Obwohl", "es", "regnet,", "gehen", "wir", "spazieren."], explain: "obwohl – подчинительный союз, поэтому в его части глагол regnet уходит в конец. Вся эта часть целиком занимает позицию 1 главного предложения – значит сразу за запятой идёт глагол gehen, и только потом wir." },
  { id: "q0113", topic: "grammar:wordorder", level: "A2", difficulty: 2, type: "mc", q: "«Ich mag keinen Kaffee, ___ Tee.» Что вставить?", rule: "r0053", opts: ["sondern", "aber", "denn", "oder"], ans: 0, explain: "sondern ставится только после отрицания (keinen) и означает «а наоборот». aber означало бы «но» и требовало бы перед собой утверждения, а не отрицания." },
  { id: "q0114", topic: "grammar:wordorder", level: "B1", difficulty: 2, type: "mc", q: "Как сказать по-немецки «Ни моя мама, ни мой папа не любят готовить»?", rule: "r0057", opts: ["Weder meine Mutter noch mein Vater kochen gern.", "Weder meine Mutter noch mein Vater kochen nicht gern.", "Weder meine Mutter oder mein Vater kochen gern.", "Meine Mutter und mein Vater kochen weder gern."], ans: 0, hint: "Отрицание уже сидит внутри самой пары союзов.", explain: "Пара weder … noch отрицает оба элемента сама, поэтому глагол kochen остаётся в обычной утвердительной форме: добавленное nicht дало бы двойное отрицание. И вторую половину пары нельзя подменить на oder – у weder партнёр только noch." },
  { id: "q0115", topic: "grammar:wordorder", level: "B1", difficulty: 3, type: "fill", q: "Впиши пропущенное слово: «Sie spricht sowohl Deutsch ___ auch Englisch.»", rule: "r0057", ans: "als", altAns: ["als"], hint: "Вторая половина пары состоит из двух слов подряд.", explain: "Конструкция работает только целиком: sowohl открывает её, а als auch – неразделимая вторая половина перед вторым элементом. Если вместо als поставить und, пара разваливается и остаётся простое перечисление без акцента «как …, так и …»." },
  { id: "q0116", topic: "grammar:wordorder", level: "B1", difficulty: 3, type: "tiles", q: "Составь: «Как мой брат, так и моя сестра живут в Берлине.»", rule: "r0057", words: ["Sowohl", "mein", "Bruder", "als", "auch", "meine", "Schwester", "wohnen", "in", "Berlin."], hint: "Вся конструкция «sowohl … als auch …» – это одно подлежащее на первом месте.", explain: "Sowohl … als auch собственной позиции не занимает: вся конструкция работает как одно подлежащее на первом месте, поэтому спрягаемый глагол идёт сразу за ней, на второй позиции. Форма wohnen во множественном числе, потому что действующих лиц двое." },
  { id: "q0117", topic: "grammar:wordorder", level: "B1", difficulty: 4, type: "mc", q: "С entweder в начале возможны два порядка слов. В каком варианте entweder само заняло первое место и предложение построено верно?", rule: "r0057", opts: ["Entweder fahren wir nach Berlin, oder wir bleiben hier.", "Entweder wir nach Berlin fahren, oder wir bleiben hier.", "Entweder nach Berlin wir fahren, oder wir bleiben hier.", "Entweder wir fahren nach Berlin, oder wir hier bleiben."], ans: 0, hint: "Если позиция 1 занята, куда обязан встать спрягаемый глагол?", explain: "Когда entweder само встаёт на первое место, спрягаемый глагол fahren обязан быть вторым, а подлежащее wir уходит за него – обычная инверсия. Во втором и третьем вариантах глагол сброшен со второй позиции, в четвёртом сломана вторая часть: oder позиции не занимает, дальше идёт обычный порядок «oder wir bleiben hier»." },
  { id: "q0118", topic: "grammar:verbs", level: "B1", difficulty: 2, type: "mc", q: "Какой вариант верен? «Er hört auf, Süßigkeiten ___.»", rule: "r0058", opts: ["zu essen", "essen", "essen zu", "zu isst"], ans: 0, hint: "Где именно стоит zu по отношению к инфинитиву?", explain: "После aufhören идёт zu-Infinitiv: смысловой глагол уходит в конец в форме инфинитива, а zu стоит прямо перед ним. Без zu оборот разваливается, после инфинитива zu не ставится, а спрягаемая форма isst невозможна – второго подлежащего в предложении нет." },
  { id: "q0119", topic: "grammar:verbs", level: "B1", difficulty: 3, type: "fill", q: "Впиши глагол abschließen в нужной форме: «Vergessen Sie nicht, die Haustür ___.»", rule: "r0058", ans: "abzuschließen", altAns: ["abzuschließen"], hint: "Глагол разделяемый – подумай, куда денется zu.", explain: "abschließen разделяемый, поэтому zu встаёт между приставкой и корнем и всё пишется слитно: ab + zu + schließen → abzuschließen. Типичная ошибка «zu abschließen» ставит zu перед приставкой, а так бывает только у неразделяемых глаголов." },
  { id: "q0120", topic: "grammar:verbs", level: "B1", difficulty: 3, type: "tiles", q: "Составь: «Она планирует переехать в следующем году.»", rule: "r0058", words: ["Sie", "hat", "vor,", "nächstes", "Jahr", "umzuziehen."], hint: "vorhaben разделяемый – и umziehen тоже.", explain: "vorhaben спрягается в главной части и разделяется: hat стоит на второй позиции, а приставка vor – в конце главной части, перед запятой. В самом обороте umziehen тоже разделяемый, поэтому zu уходит внутрь слова – umzuziehen." },
  { id: "q0121", topic: "grammar:verbs", level: "B1", difficulty: 4, type: "mc", q: "Сверни придаточное в оборот с zu: «Ich finde es wichtig, dass ich den Garten sauber halte.»", rule: "r0058", opts: ["Ich finde es wichtig, den Garten sauber zu halten.", "Ich finde es wichtig, ich den Garten sauber zu halten.", "Ich finde es wichtig, den Garten zu sauber halten.", "Ich finde es wichtig, den Garten sauber halten zu."], ans: 0, hint: "Подлежащее второй части не повторяется.", explain: "Подлежащее в обеих частях одно и то же (ich), поэтому во второй части оно исчезает вместе с dass, а спрягаемое halte превращается в инфинитив halten и уходит в конец с zu прямо перед собой. Повторить ich нельзя, и zu не отрывается от инфинитива." },
  { id: "q0122", topic: "grammar:verbs", level: "A2", difficulty: 2, type: "mc", q: "Вставь пропущенное слово: «Ich kaufe kein Brot, ___ Kuchen.» (Я покупаю не хлеб, а торт.)", rule: "r0059", opts: ["sondern", "aber", "denn", "oder"], ans: 0, hint: "Перед пропуском стоит kein – отрицание, которое нужно заменить верным вариантом.", explain: "kein Brot отрицает хлеб, и sondern ставит на его место Kuchen: хлеб не куплен вовсе. aber отрицание не снимает, а лишь добавляет к нему второе утверждение, denn вводит причину, oder – выбор, и ни один из них не выражает замену «не X, а Y»." },
  { id: "q0123", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "tiles", q: "Составь: «Она придёт не сегодня, а завтра.»", rule: "r0059", words: ["Sie", "kommt", "nicht", "heute,", "sondern", "morgen."], hint: "Отрицается обстоятельство времени heute, поэтому nicht стоит прямо перед ним.", explain: "nicht стоит непосредственно перед тем словом, которое отрицается (heute), а sondern вводит замену – morgen. sondern – сочинительный союз на позиции 0, поэтому после запятой порядок слов не меняется и глагол в конец не уходит." },
  { id: "q0124", topic: "grammar:verbs", level: "A2", difficulty: 4, type: "fill", q: "Вставь союз: «Das ist nicht mein Buch, ___ ich darf es lesen.» (Это не моя книга, но мне можно её читать.)", rule: "r0059", ans: "aber", altAns: ["aber", "Aber"], hint: "Заменяется ли здесь «моя книга» на другого владельца – или к отрицанию просто добавляется новая мысль?", explain: "Отрицание остаётся в силе: книга по-прежнему не моя, а вторая часть лишь добавляет совместимый с этим факт – значит нужен aber. sondern потребовался бы только при замене отрицаемого: Das ist nicht mein Buch, sondern deins." },
  { id: "q0125", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "mc", q: "Как правильно сказать «Он не поёт, а танцует»?", rule: "r0059", opts: ["Er singt nicht, sondern tanzt.", "Er singt nicht, aber tanzt.", "Er nicht singt, sondern tanzt.", "Er singt nicht, sondern er tanzt nicht."], ans: 0, hint: "Через sondern заменяется не только существительное, но и само действие.", explain: "Отрицается действие singt, и sondern ставит на его место tanzt; порядок слов после союза не меняется, подлежащее не повторяется. Вариант с aber не отменил бы пение, а «Er nicht singt» нарушает второе место глагола: nicht не может стоять перед спрягаемым глаголом." },
  { id: "q0126", topic: "grammar:wordorder", level: "A2", difficulty: 2, type: "mc", q: "Вставь пропущенное слово: «Es regnet. ___ bleibe ich zu Hause.» (Идёт дождь. Поэтому я остаюсь дома.)", rule: "r0060", opts: ["Trotzdem", "Deswegen", "Obwohl", "Weil"], ans: 1, hint: "Подставь «поэтому» – смысл сохраняется?", explain: "Остаться дома – ожидаемое следствие дождя, поэтому нужно deswegen (= deshalb). Trotzdem означало бы результат вопреки причине, а weil и obwohl – подчинительные союзы: после них спрягаемый глагол ушёл бы в конец (…, weil es regnet)." },
  { id: "q0127", topic: "grammar:wordorder", level: "A2", difficulty: 3, type: "tiles", q: "Составь вторую часть: «Ich habe keine Zeit.» + «Поэтому я не приду.»", rule: "r0060", words: ["Deshalb", "komme", "ich", "nicht."], hint: "Deshalb занимает позицию 1 – что обязано стоять сразу после него?", explain: "deshalb – наречие, оно занимает первую позицию, спрягаемый глагол komme обязан остаться на второй, а подлежащее ich уходит за глагол. Вариант «Deshalb ich komme nicht» ставит перед глаголом сразу два элемента и потому неверен." },
  { id: "q0128", topic: "grammar:wordorder", level: "A2", difficulty: 3, type: "fill", q: "Вставь подходящее наречие: «Er hat viel gearbeitet. ___ ist er nicht müde.» (Он много работал. Тем не менее он не устал.)", rule: "r0060", ans: "Trotzdem", altAns: ["Trotzdem", "trotzdem"], hint: "Результат противоречит причине – просится «всё равно / несмотря на это».", explain: "Много работы обычно ведёт к усталости, но результат этой причине противоречит – это уступка, значит trotzdem; deshalb дало бы бессмысленное «поэтому он не устал». Обрати внимание на порядок: наречие на позиции 1, глагол ist на второй, подлежащее er – после глагола." },
  { id: "q0129", topic: "grammar:wordorder", level: "A2", difficulty: 4, type: "mc", q: "Какая пара предложений передаёт тот же смысл, что «Ich gehe spazieren, obwohl es regnet»?", rule: "r0060", opts: ["Es regnet. Trotzdem gehe ich spazieren.", "Es regnet. Deswegen gehe ich spazieren.", "Es regnet. Trotzdem ich gehe spazieren.", "Es regnet. Obwohl gehe ich spazieren."], ans: 0, hint: "У obwohl есть парное наречие – какое?", explain: "Уступительному союзу obwohl соответствует наречие trotzdem, и наречие на позиции 1 оставляет глагол на второй: Trotzdem gehe ich. Deswegen переворачивает смысл на следствие, «Trotzdem ich gehe» нарушает второе место глагола, а obwohl – подчинительный союз и не может открывать самостоятельное предложение с глаголом на втором месте." },
  { id: "q0130", topic: "grammar:cases", level: "B1", difficulty: 2, type: "mc", q: "Выбери правильный артикль: die Rechte ___ Bürger (права граждан).", rule: "r0061", opts: ["des", "der", "dem", "den"], ans: 1, hint: "Множественное число, вопрос «чей?».", explain: "Bürger здесь во множественном числе, а в Genitiv Plural артикль у всех родов один – der. des – это Genitiv Singular мужского и среднего рода (des Bürgers), dem и den относятся к Dativ и на вопрос «чей?» не отвечают." },
  { id: "q0131", topic: "grammar:cases", level: "B1", difficulty: 3, type: "fill", q: "Впиши притяжательное местоимение в нужной форме (mein): die Bücher ___ Freunde – книги моих друзей.", rule: "r0061", ans: "meiner", altAns: ["meiner"], hint: "Окончание такое же, как у артикля der.", explain: "В Genitiv Plural притяжательное местоимение копирует артикль der и получает окончание -er: meiner Freunde. Формы meines и meinem/meinen – это Genitiv Singular и Dativ, в Genitiv Plural они ломают падеж." },
  { id: "q0132", topic: "grammar:cases", level: "B1", difficulty: 3, type: "fill", q: "Впиши существительное das Haus во множественном числе: die Farbe der ___ – цвет домов.", rule: "r0061", ans: "Häuser", altAns: ["Häuser", "Haeuser"], hint: "Осторожно: это не Dativ.", explain: "В Genitiv Plural существительное остаётся чистой формой множественного числа: der Häuser. Окончание -n (den Häusern) – признак Dativ Plural, а -es (des Hauses) – Genitiv Singular, и оба здесь дают другой падеж." },
  { id: "q0133", topic: "grammar:cases", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Во время переговоров он ничего не сказал.»", rule: "r0061", words: ["Während", "der", "Verhandlungen", "hat", "er", "nichts", "gesagt."], hint: "Предлог während требует Genitiv.", explain: "Während требует Genitiv, а во множественном числе это der плюс форма Plural без всякого окончания: der Verhandlungen. Группа Während der Verhandlungen занимает первое место, поэтому спрягаемый глагол hat стоит вторым, а причастие gesagt уходит в конец." },
  { id: "q0134", topic: "grammar:wordorder", level: "B1", difficulty: 2, type: "mc", q: "Выбери правильное окончание предложения: «Ich bleibe hier, bis ich mit der Arbeit ___»", rule: "r0062", opts: ["bin fertig.", "fertig bin.", "fertig sein.", "werde fertig."], ans: 1, hint: "bis вводит придаточное.", explain: "bis – подчинительный союз: он открывает Nebensatz, и спрягаемый глагол bin встаёт на самое последнее место, после fertig. Порядок «bis ich bin fertig» – это порядок главного предложения, в придаточном он невозможен." },
  { id: "q0135", topic: "grammar:wordorder", level: "B1", difficulty: 3, type: "fill", q: "Впиши глагол zurückkommen в нужной форме: «Ich warte auf dich, bis du ___» – Я подожду тебя, пока ты не вернёшься.", rule: "r0062", ans: "zurückkommst", altAns: ["zurückkommst", "zurueckkommst"], hint: "Русское «не» здесь не переводится.", explain: "Русское «пока не» передаётся одним bis: отрицания в немецком придаточном нет, nicht перевернул бы смысл. Спрягаемая форма zurückkommst при этом уходит в самый конец придаточного." },
  { id: "q0136", topic: "grammar:wordorder", level: "B1", difficulty: 3, type: "tiles", q: "Составь: «С тех пор как я живу в Германии, я учу немецкий.»", rule: "r0062", words: ["Seitdem", "ich", "in", "Deutschland", "wohne,", "lerne", "ich", "Deutsch."], hint: "Придаточное стоит первым – что тогда с главным?", explain: "Придаточное с seitdem идёт первым целиком, поэтому его глагол wohne стоит в конце, перед запятой. Занятое первое место заставляет главное предложение начинаться со спрягаемого глагола: lerne ich Deutsch, а не ich lerne Deutsch." },
  { id: "q0137", topic: "grammar:wordorder", level: "B1", difficulty: 4, type: "mc", q: "Какое предложение построено правильно?", rule: "r0062", opts: ["Seit ich wohne hier, spreche ich besser.", "Seit ich hier wohne, spreche ich besser.", "Seit einem Jahr ich wohne hier.", "Seitdem einem Jahr wohne ich hier."], ans: 1, hint: "seit бывает и союзом, и предлогом – порядок слов разный.", explain: "Как союз seit вводит придаточное, и спрягаемый глагол wohne уходит в конец, а главное предложение после запятой начинается с глагола spreche. Как предлог seit идёт с Dativ и придаточного не образует (Seit einem Jahr wohne ich hier), а seitdem предлогом не бывает вовсе." },
  { id: "q0138", topic: "grammar:wordorder", level: "A2", difficulty: 2, type: "mc", q: "Какой союз отправляет спрягаемый глагол в конец предложения?", rule: "r0053", opts: ["denn", "aber", "weil", "deshalb"], ans: 2, explain: "weil – подчинительный союз: он открывает Nebensatz, и спрягаемый глагол уезжает на последнее место. denn и aber – сочинительные, стоят на позиции 0 и порядок не трогают. deshalb – наречие, оно занимает позицию 1 и вызывает инверсию." },
  { id: "q0139", topic: "grammar:wordorder", level: "B1", difficulty: 2, type: "mc", q: "Какая пара союзов сама выражает отрицание, так что отдельное nicht или kein уже не нужно?", rule: "r0057", opts: ["sowohl … als auch", "entweder … oder", "weder … noch", "nicht nur … sondern auch"], ans: 2, hint: "Переведи каждую пару на русский и посмотри, где уже есть «не».", explain: "weder … noch значит «ни …, ни …»: отрицание встроено в сам союз, поэтому глагол остаётся в утвердительной форме – Er trinkt weder Kaffee noch Tee. sowohl … als auch и entweder … oder не отрицают ничего, а в nicht nur … sondern auch отрицается только первая часть, вторая как раз утверждается." },
  { id: "q0140", topic: "grammar:verbs", level: "B1", difficulty: 2, type: "mc", q: "При каком условии придаточное с dass можно свернуть в оборот с zu + Infinitiv?", rule: "r0058", opts: ["Когда действующее лицо второй части – это подлежащее главного предложения или названо в нём как дополнение", "Когда в главном и придаточном разные подлежащие и второе нигде не названо", "Когда в главном предложении стоит модальный глагол", "Когда придаточное стоит перед главным"], ans: 0, hint: "Подлежащее оборота не пишется – значит, его должно быть откуда взять.", explain: "В обороте с zu второе подлежащее не называется вовсе, поэтому его достают из главного предложения: это либо подлежащее главного (Er hört auf, Süßigkeiten zu essen), либо его дополнение при глаголах вроде bitten и erlauben (Ich bitte dich, die Tür zu schließen). Если действующее лицо второй части в главном не названо, свернуть нельзя – нужен dass-Satz." },
  { id: "q0141", topic: "grammar:verbs", level: "A2", difficulty: 2, type: "mc", q: "Чем sondern отличается от aber после отрицания?", rule: "r0059", opts: ["sondern отменяет отрицаемое и ставит на его место второе", "sondern оставляет первую часть в силе и добавляет вторую", "sondern отправляет спрягаемый глагол в конец предложения", "перед sondern запятая не ставится"], ans: 0, hint: "Спроси себя: после союза первая часть всё ещё верна или уже отменена?", explain: "sondern снимает отрицание и подставляет правильный вариант: Ich kaufe kein Brot, sondern Kuchen – хлеба нет вообще. aber отрицание сохраняет и лишь добавляет второе: Er ist nicht reich, aber glücklich – он действительно небогат. Глагол в конец sondern не отправляет: это сочинительный союз на позиции 0." },
  { id: "q0142", topic: "grammar:wordorder", level: "A2", difficulty: 2, type: "mc", q: "Что происходит со спрягаемым глаголом, если предложение начинается с trotzdem или deshalb?", rule: "r0060", opts: ["Он уходит в конец предложения", "Он остаётся на второй позиции, а подлежащее встаёт после него", "Он стоит на первом месте, перед наречием", "Он стоит сразу после подлежащего, как в обычном порядке"], ans: 1, hint: "trotzdem и deshalb – наречия, а не союзы.", explain: "Наречие trotzdem или deshalb само занимает позицию 1, поэтому спрягаемый глагол остаётся на позиции 2, а подлежащее уезжает за него: Trotzdem gehe ich spazieren. В конец глагол отправляют подчинительные союзы weil и obwohl, а «Trotzdem ich gehe» неверно: перед глаголом оказалось бы два элемента." },
  { id: "q0143", topic: "grammar:cases", level: "B1", difficulty: 2, type: "mc", q: "Что происходит с самим существительным в Genitiv Plural?", rule: "r0061", opts: ["получает -(e)s", "получает -n", "получает -er", "не получает никакого окончания"], ans: 3, hint: "Сравни с Dativ Plural и с Genitiv Singular.", explain: "В Genitiv Plural работает только артикль der, а существительное остаётся чистой формой множественного числа: der Männer, der Häuser. Окончание -(e)s бывает лишь в Genitiv Singular мужского и среднего рода (des Mannes), -n – в Dativ Plural (mit den Kindern), а -er принадлежит артиклю и притяжательным (meiner), но не существительному." },
  { id: "q0144", topic: "grammar:wordorder", level: "B1", difficulty: 2, type: "mc", q: "Какой союз называет конечную точку – момент, до которого длится действие главного предложения?", rule: "r0062", opts: ["seit", "seitdem", "bis", "denn"], ans: 2, hint: "Вопрос «до каких пор?», а не «с каких пор?».", explain: "bis отвечает на вопрос «до какого момента?»: действие главного предложения длится, пока не наступит действие придаточного, и глагол придаточного уходит в конец. seit и seitdem называют, наоборот, начальную точку – момент, с которого действие продолжается до сих пор; denn вообще сочинительный союз и придаточного не образует." },
  { id: "q0145", topic: "grammar:adjectives", level: "A1", difficulty: 2, type: "mc", q: "Выбери правильную форму: «Ich habe ___ Woche einen Termin.»", rule: "r0019", opts: ["nächste", "nächsten", "nächstes", "nächster"], ans: 0, hint: "Woche – женский род; артикля перед прилагательным нет.", explain: "Die Woche женского рода, а указание времени без предлога стоит в Akkusativ; у женского рода в Nominativ и Akkusativ прилагательное берёт -e: nächste Woche. Форма nächsten была бы Dativ или мужской Akkusativ, nächstes – средний род." },
  { id: "q0146", topic: "grammar:adjectives", level: "A1", difficulty: 3, type: "fill", q: "Впиши форму прилагательного nächst: «Ich komme ___ Montag.»", rule: "r0019", ans: "nächsten", altAns: ["nächsten", "Nächsten", "naechsten", "Naechsten"], hint: "Der Montag – мужской род; спроси себя: когда? – в следующий понедельник.", explain: "Указание времени без предлога стоит в Akkusativ, а der Montag мужского рода – именно там артикль и окончание меняются на -en: nächsten Montag. Форма nächste дала бы Nominativ, то есть понедельник стал бы подлежащим." },
  { id: "q0147", topic: "grammar:adjectives", level: "A1", difficulty: 3, type: "tiles", q: "Составь: «В следующем году я учу немецкий.»", rule: "r0019", words: ["Im", "nächsten", "Jahr", "lerne", "ich", "Deutsch."], hint: "im = in + dem; обстоятельство впереди, а глагол вторым.", explain: "im – это in + dem, то есть Dativ, а в Dativ прилагательное всегда получает -en: im nächsten Jahr. Обстоятельство занимает первое место, поэтому спрягаемый глагол lerne остаётся на втором, а подлежащее ich уходит за него." },
  { id: "q0148", topic: "grammar:adjectives", level: "A1", difficulty: 4, type: "mc", q: "Выбери правильную форму: «Sie trägt die ___ Bluse.»", rule: "r0019", opts: ["lila", "lilae", "lilane", "lilas"], ans: 0, hint: "Прилагательные на -a – особая группа.", explain: "rosa, lila, prima, beige не склоняются вообще: даже перед существительным они остаются в словарной форме – die lila Bluse, der rosa Mantel. Окончание сюда просто некуда прицепить." },
  { id: "q0149", topic: "grammar:wordorder", level: "A1", difficulty: 2, type: "tiles", q: "Составь: «Я учу немецкий, потому что это интересно.»", rule: "r0023", words: ["Ich", "lerne", "Deutsch,", "weil", "es", "interessant", "ist."], hint: "Перед weil запятая, а спрягаемый глагол придаточного уезжает в самый конец.", explain: "weil открывает Nebensatz, поэтому спрягаемый глагол ist встаёт после прилагательного interessant, в самом конце. В главном предложении порядок обычный: подлежащее Ich, глагол lerne на втором месте." },
  { id: "q0150", topic: "grammar:wordorder", level: "A1", difficulty: 3, type: "mc", q: "Выбери правильное продолжение: «Er kommt nicht, weil ___»", rule: "r0023", opts: ["er arbeiten muss", "er muss arbeiten", "muss er arbeiten", "arbeiten er muss"], ans: 0, hint: "Спрягаемый здесь модальный глагол – значит именно он идёт последним.", explain: "В придаточном с weil последнее место занимает спрягаемый глагол, то есть muss, а инфинитив arbeiten стоит перед ним: weil er arbeiten muss. Вариант «weil er muss arbeiten» просто копирует порядок главного предложения." },
  { id: "q0151", topic: "grammar:wordorder", level: "A1", difficulty: 3, type: "fill", q: "Впиши глагол wollen в нужной форме: «Sie bleibt zu Hause, weil sie schlafen ___.»", rule: "r0023", ans: "will", altAns: ["will", "Will"], hint: "Подлежащее придаточного – sie (она).", explain: "Последним в придаточном стоит именно спрягаемая часть, поэтому модальный глагол идёт после инфинитива schlafen и спрягается по подлежащему sie: will. Оставить там инфинитив wollen нельзя – тогда в предложении не будет ни одной спрягаемой формы." },
  { id: "q0152", topic: "grammar:wordorder", level: "A1", difficulty: 4, type: "mc", q: "Выбери верный порядок: «Er ist müde, weil er gestern lange ___»", rule: "r0023", opts: ["hat arbeiten müssen", "arbeiten müssen hat", "gearbeitet hat müssen", "arbeiten hat müssen"], ans: 0, hint: "Это исключение: в конце три глагольные части.", explain: "Обычно спрягаемый глагол в Nebensatz последний, но когда глагольных частей три (Perfekt модального), hat перескакивает вперёд обоих инфинитивов: weil er hat arbeiten müssen. Порядок «arbeiten müssen hat» – как раз типичная ошибка, а причастие gearbeitet невозможно: у модального вместо него стоит Ersatzinfinitiv müssen." },
  { id: "q0153", topic: "grammar:cases", level: "A1", difficulty: 2, type: "mc", q: "Выбери правильную форму: «Ich kaufe ___ Apfel.»", rule: "r0024", opts: ["einen", "ein", "einem", "eines"], ans: 0, hint: "Спроси: кого? что? я покупаю.", explain: "Apfel – прямой объект, действие направлено на него, значит Akkusativ, а в мужском роде ein превращается в einen. Форма ein – это Nominativ, тогда яблоко было бы тем, кто покупает; einem – Dativ, то есть адресат." },
  { id: "q0154", topic: "grammar:cases", level: "A1", difficulty: 3, type: "fill", q: "Впиши артикль: «Er ist ___ Lehrer.»", rule: "r0024", ans: "ein", altAns: ["ein", "Ein"], hint: "sein не направляет действие на объект.", explain: "После sein, werden, bleiben вторая часть стоит в Nominativ: глагол sein не затрагивает объект, а приравнивает две вещи друг к другу, поэтому падеж остаётся тем же, что у подлежащего. Отсюда «Er ist ein Lehrer», а «einen Lehrer» было бы Akkusativ, как будто учителя покупают." },
  { id: "q0155", topic: "grammar:cases", level: "A1", difficulty: 3, type: "tiles", q: "Составь: «Я даю тебе книгу.»", rule: "r0024", words: ["Ich", "gebe", "dir", "das", "Buch."], hint: "Кому? – Dativ. Что? – Akkusativ.", explain: "У geben два объекта: книга – прямой (Akkusativ, das Buch), а адресат – косвенный (Dativ, dir). Местоимение в Dativ стоит перед существительным-объектом, поэтому «gebe dir das Buch», а не «gebe das Buch dir»." },
  { id: "q0156", topic: "grammar:cases", level: "A1", difficulty: 4, type: "mc", q: "Выбери правильную форму: «Wir fahren mit ___ Bus.»", rule: "r0024", opts: ["dem", "den", "der", "das"], ans: 0, hint: "mit, bei, nach, von, zu, aus – одна группа предлогов.", explain: "Предлог mit всегда требует Dativ, независимо от смысла, а der Bus в Dativ даёт dem Bus. Форма den – Akkusativ мужского рода, она появилась бы после durch, für, gegen, ohne, um, но не после mit." },
  { id: "q0157", topic: "grammar:cases", level: "A2", difficulty: 2, type: "mc", q: "Выбери правильную форму: «Ich danke ___ für die Hilfe.» (обращение на «Вы»)", rule: "r0025", opts: ["Sie", "Ihnen", "Ihr", "Ihren"], ans: 1, hint: "Глагол danken требует вопроса «Wem?».", explain: "danken управляет Dativ, а вежливое Sie в Dativ превращается в Ihnen. Форма Sie – это Nominativ или Akkusativ, после danken она невозможна; Ihr и Ihren – притяжательные формы, а здесь нужно личное местоимение." },
  { id: "q0158", topic: "grammar:cases", level: "A2", difficulty: 3, type: "fill", q: "Вставь артикль в Dativ Plural: «Ich danke ___ Kollegen für die Hilfe.»", rule: "r0025", ans: "den", altAns: ["den", "Den"], hint: "Множественное число, вопрос «Wem?».", explain: "После danken лицо стоит в Dativ, а определённый артикль множественного числа в Dativ – den. Артикль die был бы Nominativ или Akkusativ, и тогда получилось бы «я благодарю кого-что», чего этот глагол не допускает." },
  { id: "q0159", topic: "grammar:cases", level: "A2", difficulty: 3, type: "tiles", q: "Составь: «Моя дочь всегда мне помогает.»", rule: "r0025", words: ["Meine", "Tochter", "hilft", "mir", "immer."], hint: "Помни, какой падеж требует helfen.", explain: "helfen ставит лицо в Dativ, поэтому «мне» – это mir, а не mich. Наречие immer стоит после дативного дополнения, в конце предложения." },
  { id: "q0160", topic: "grammar:cases", level: "A2", difficulty: 4, type: "mc", q: "Выбери правильный вариант: «Он ничего не ответил.» – «Er antwortete ___.»", rule: "r0025", opts: ["nichts", "niemandem", "nichtem", "nichtes"], ans: 0, hint: "Что здесь стоит после глагола: лицо или содержание ответа?", explain: "У antworten в Dativ идёт только адресат (Ich antworte dir), а содержание ответа стоит в Akkusativ: Er antwortete nichts. Форма niemandem – это Dativ лица, она дала бы смысл «никому не ответил», а nichtem и nichtes вообще не существуют." },
  { id: "q0161", topic: "grammar:cases", level: "A2", difficulty: 2, type: "tiles", q: "Составь: «Я даю мужчине книгу.»", rule: "r0026", words: ["Ich", "gebe", "dem", "Mann", "das", "Buch."], hint: "Два существительных – вспомни порядок.", explain: "Когда оба дополнения существительные, сначала идёт Dativ (dem Mann, кому), потом Akkusativ (das Buch, что). Порядок «das Buch dem Mann» возможен только при особом выделении." },
  { id: "q0162", topic: "grammar:cases", level: "A2", difficulty: 3, type: "fill", q: "Замени существительное местоимением: «Er zeigt der Kundin den Weg.» → «Er zeigt ___ den Weg.»", rule: "r0026", ans: "ihr", altAns: ["ihr", "Ihr"], hint: "Женский род, Dativ.", explain: "der Kundin – это Dativ женского рода, соответствующее личное местоимение – ihr. Местоимение притягивается вперёд существительного, поэтому остаётся перед den Weg." },
  { id: "q0163", topic: "grammar:cases", level: "A2", difficulty: 3, type: "mc", q: "«Он показывает ей дорогу» – замени оба дополнения местоимениями: «Er zeigt ___.»", rule: "r0026", opts: ["ihr ihn", "ihn ihr", "sie ihr", "ihr sie"], ans: 1, hint: "Два личных местоимения – какое первое?", explain: "Когда оба дополнения – личные местоимения, Akkusativ идёт первым: ihn (den Weg) перед ihr (der Kundin). Вариант «ihr ihn» повторяет порядок с существительными, а sie – это Nominativ или Akkusativ, для адресата нужен Dativ ihr." },
  { id: "q0164", topic: "grammar:cases", level: "A2", difficulty: 4, type: "mc", q: "Выбери правильный порядок: «Я дам ему один.» – «Ich gebe ___.»", rule: "r0026", opts: ["eins ihm", "ihm eins", "ihn eins", "eins ihn"], ans: 1, hint: "eins – не личное местоимение.", explain: "Правило «Akkusativ впереди» работает только тогда, когда оба слова – личные местоимения. Слово eins неопределённое, поэтому действует обычный порядок Dativ перед Akkusativ: ihm eins. Форма ihn – Akkusativ, она не может обозначать адресата." },
  { id: "q0165", topic: "grammar:cases", level: "A2", difficulty: 2, type: "fill", q: "Вставь артикль: «Ich gebe ___ Mann das Buch.»", rule: "r0027", ans: "dem", altAns: ["dem", "Dem"], hint: "Кому? – Wem?", explain: "Глагол geben требует двух дополнений: адресат в Dativ и предмет в Akkusativ. Мужской род в Dativ даёт артикль dem; den был бы Akkusativ, но эту роль уже занимает das Buch." },
  { id: "q0166", topic: "grammar:cases", level: "A2", difficulty: 3, type: "mc", q: "Выбери правильную форму: «Er schenkt der Frau ___ Ring.»", rule: "r0027", opts: ["ein", "einen", "einem", "eines"], ans: 1, hint: "Кольцо – это «что?», не «кому?».", explain: "Подарок – прямой объект, он стоит в Akkusativ, а неопределённый артикль мужского рода в Akkusativ – einen. Форма einem – Dativ, она уже отдана адресату der Frau, а ein здесь был бы Nominativ." },
  { id: "q0167", topic: "grammar:cases", level: "A2", difficulty: 3, type: "tiles", q: "Составь: «Мы показываем детям город.»", rule: "r0027", words: ["Wir", "zeigen", "den", "Kindern", "die", "Stadt."], hint: "Сначала «кому», потом «что»; не забудь окончание в Dativ Plural.", explain: "У zeigen два дополнения: адресат в Dativ (den Kindern) стоит перед объектом в Akkusativ (die Stadt). В Dativ Plural существительное получает -n, поэтому Kinder превращается в Kindern." },
  { id: "q0168", topic: "grammar:cases", level: "A2", difficulty: 4, type: "fill", q: "Поставь существительное в нужную форму: «Ich schicke den ___ eine Nachricht.» (die Freunde)", rule: "r0027", ans: "Freunden", altAns: ["Freunden", "freunden"], hint: "Dativ Plural требует особого окончания.", explain: "Адресат при schicken стоит в Dativ, а в Dativ Plural к существительному добавляется -n: die Freunde → den Freunden. Без этого -n форма осталась бы Nominativ или Akkusativ и не согласовалась бы с артиклем den." },
  { id: "q0169", topic: "grammar:cases", level: "A1", difficulty: 2, type: "mc", q: "Вставь артикль: «Ich sehe ___ Mann.»", rule: "r0028", opts: ["der", "den", "dem", "das"], ans: 1, hint: "Wen sehe ich? Это прямой объект.", explain: "sehen требует Akkusativ: Mann здесь прямой объект (Wen?), а у мужского рода в Akkusativ der превращается в den. der Mann было бы Nominativ, то есть подлежащим, но подлежащее уже ich." },
  { id: "q0170", topic: "grammar:cases", level: "A1", difficulty: 3, type: "fill", q: "Вставь артикль: «Ich helfe ___ Frau.»", rule: "r0028", ans: "der", altAns: ["der", "Der"], hint: "Глагол helfen требует Dativ, род женский.", explain: "helfen управляет Dativ, а у женского рода в Dativ артикль die меняется на der. Вариант die Frau дал бы Akkusativ, которого этот глагол не допускает, а dem – это Dativ мужского и среднего рода." },
  { id: "q0171", topic: "grammar:cases", level: "A1", difficulty: 3, type: "tiles", q: "Составь: «Это принадлежит ребёнку.»", rule: "r0028", words: ["Das", "gehört", "dem", "Kind."], hint: "gehören требует Dativ, Kind – средний род.", explain: "gehören всегда даёт адресата в Dativ, поэтому das Kind превращается в dem Kind. Спрягаемый глагол gehört стоит на втором месте, дополнение в Dativ – после него." },
  { id: "q0172", topic: "grammar:cases", level: "A1", difficulty: 4, type: "fill", q: "Поставь существительное в нужную форму: «Ich gebe den ___ das Buch.» (die Kinder)", rule: "r0028", ans: "Kindern", altAns: ["Kindern", "kindern"], hint: "Dativ Plural: не только артикль den, но и окончание у существительного.", explain: "geben даёт адресата в Dativ: во множественном числе артикль становится den, а само существительное получает -n – den Kindern. Исключение только там, где множественное уже на -n/-en или на -s: den Frauen, den Autos." },
  { id: "q0173", topic: "grammar:cases", level: "A2", difficulty: 2, type: "mc", q: "Выбери верное продолжение: «Ich gehe nicht aus, weil ich ___»", rule: "r0029", opts: ["lernen muss", "muss lernen", "lerne muss", "muss lerne"], ans: 0, hint: "Спрягаемый глагол здесь muss.", explain: "weil открывает Nebensatz, поэтому спрягаемый глагол muss уезжает на самое последнее место, а инфинитив lernen встаёт прямо перед ним. «muss lernen» – это порядок главного предложения (Ich muss lernen), в придаточном он ломается." },
  { id: "q0174", topic: "grammar:cases", level: "A2", difficulty: 3, type: "tiles", q: "Составь: «Она устала, потому что много работала.»", rule: "r0029", words: ["Sie", "ist", "müde,", "weil", "sie", "viel", "gearbeitet", "hat."], hint: "Perfekt в придаточном: сначала Partizip II, потом спрягаемый глагол.", explain: "В Nebensatz спрягаемый глагол hat уходит в самый конец, а Partizip II gearbeitet стоит непосредственно перед ним. Перед weil обязательна запятая, поэтому она приклеена к müde." },
  { id: "q0175", topic: "grammar:cases", level: "A2", difficulty: 3, type: "fill", q: "Вставь глагол sein в нужной форме: «Er kommt nicht, weil er krank ___.»", rule: "r0029", ans: "ist", altAns: ["ist", "Ist"], hint: "Форма sein для er – и место у неё особое.", explain: "sein спрягается как er ist, но weil делает предложение придаточным, и спрягаемая форма встаёт после прилагательного krank, на последнее место. Порядок «weil er ist krank» – это схема главного предложения." },
  { id: "q0176", topic: "grammar:cases", level: "A2", difficulty: 4, type: "mc", q: "Выбери верное придаточное: «Ich weiß, dass der Arzt das Kind ___»", rule: "r0029", opts: ["hat operieren müssen", "operieren müssen hat", "operiert hat müssen", "müssen operieren hat"], ans: 0, hint: "Глагольных частей три – работает исключение.", explain: "Когда в придаточном три глагольные части (hat + operieren + müssen), спрягаемый глагол hat не остаётся последним, а встаёт перед обоими инфинитивами. Модальный при этом стоит в форме инфинитива müssen (Ersatzinfinitiv), а не Partizip II gemusst." },
  { id: "q0177", topic: "grammar:cases", level: "A1", difficulty: 2, type: "mc", q: "Вставь нужную форму: «Ich bin ___ Büro.»", rule: "r0030", opts: ["im", "ins", "in", "in der"], ans: 0, hint: "Вопрос Wo? – какой падеж?", explain: "Wo? означает Dativ: das Büro даёт in dem Büro, а in + dem всегда сливаются в im. ins – это in + das, то есть Akkusativ и направление (Wohin?), а in der относится к женскому роду." },
  { id: "q0178", topic: "grammar:cases", level: "A1", difficulty: 3, type: "fill", q: "Вставь слитную форму предлога с артиклем: «Er steht ___ Fenster.»", rule: "r0030", ans: "am", altAns: ["am", "Am"], hint: "an + dem = ?", explain: "das Fenster в Dativ даёт an dem Fenster, а an с артиклем dem сливается в am. Форма ans (an + das) означала бы движение к окну (Wohin?), но здесь человек стоит на месте." },
  { id: "q0179", topic: "grammar:cases", level: "A1", difficulty: 3, type: "tiles", q: "Составь: «Книга лежит на полке.»", rule: "r0030", words: ["Das", "Buch", "liegt", "im", "Regal."], hint: "Wo? – значит одно слитное слово вместо in dem.", explain: "liegen отвечает на вопрос Wo?, поэтому нужен Dativ: in dem Regal превращается в im Regal и занимает одну плитку. Спрягаемый глагол liegt стоит на втором месте." },
  { id: "q0180", topic: "grammar:cases", level: "A1", difficulty: 4, type: "mc", q: "Вставь нужную форму: «Die Kinder spielen ___ Küche.»", rule: "r0030", opts: ["im", "in dem", "in der", "ins"], ans: 2, hint: "Küche – какого рода?", explain: "Küche женского рода, в Dativ die становится der, а с der слияния не бывает – только in der Küche. im получилось бы из in + dem, то есть для мужского и среднего рода, а ins – это Akkusativ и направление." },
  { id: "q0181", topic: "grammar:cases", level: "A1", difficulty: 2, type: "mc", q: "Выбери форму: «Das Buch liegt ___ Tisch.» (Wo?)", rule: "r0031", opts: ["auf dem", "auf den", "auf das", "auf der"], ans: 0, hint: "Вопрос Wo? – книга лежит, никуда не движется.", explain: "Книга просто лежит на месте, поэтому auf идёт с Dativ: der Tisch → dem Tisch. Форма auf den Tisch – это Akkusativ, он отвечал бы на Wohin?, а auf der – Dativ женского рода, тогда как Tisch мужского." },
  { id: "q0182", topic: "grammar:cases", level: "A1", difficulty: 3, type: "fill", q: "Впиши артикль: «Das Bild hängt an ___ Wand.»", rule: "r0031", ans: "der", altAns: ["der", "Der"], hint: "Wand – женского рода, вопрос к группе – Wo?", explain: "Картина висит на месте: Wo? → an + Dativ. У die Wand Dativ даёт форму der Wand. Akkusativ an die Wand отвечал бы на Wohin? – если бы картину только вешали на стену." },
  { id: "q0183", topic: "grammar:cases", level: "A1", difficulty: 3, type: "tiles", q: "Составь: «Кошка сидит под стулом.»", rule: "r0031", words: ["Die", "Katze", "sitzt", "unter", "dem", "Stuhl."], hint: "sitzen – это положение, а не движение.", explain: "sitzen отвечает на вопрос Wo?, поэтому unter требует Dativ: der Stuhl → dem Stuhl. Спрягаемый глагол sitzt стоит на втором месте, а предложная группа замыкает предложение." },
  { id: "q0184", topic: "grammar:cases", level: "A1", difficulty: 4, type: "mc", q: "Выбери форму: «Der Tisch steht ___ Pflanzen.» (Wo?)", rule: "r0031", opts: ["zwischen die", "zwischen den", "zwischen der", "zwischen dem"], ans: 1, hint: "Pflanzen стоит во множественном числе.", explain: "Wo? → zwischen с Dativ, а во множественном числе Dativ даёт артикль den: die Pflanzen → den Pflanzen. Вариант zwischen die Pflanzen – это Akkusativ и вопрос Wohin?, а der и dem здесь были бы формами единственного числа." },
  { id: "q0185", topic: "grammar:verbs", level: "A2", difficulty: 2, type: "fill", q: "Разверни стяжение: «Wie geht's?» = «Wie geht ___?»", rule: "r0055", ans: "es", altAns: ["es", "Es"], hint: "За апострофом прячется местоимение.", explain: "В geht's апостроф стоит на месте выпавшей e, а s – остаток местоимения es: полная форма Wie geht es? Это es здесь обязательное подлежащее, поэтому при развёртывании оно возвращается целиком." },
  { id: "q0186", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "mc", q: "Что скрыто в 's в предложении «Wenn's regnet, bleibe ich zu Hause.»?", rule: "r0055", opts: ["es", "das", "dass", "uns"], ans: 0, hint: "Подставь полную форму и прочитай фразу целиком.", explain: "Wenn's = wenn es: стяжение съедает e у местоимения es, и получается Wenn es regnet, bleibe ich zu Hause. Вариант das дал бы другое слово и другой смысл, а dass – союз, но место союза здесь уже занято словом wenn." },
  { id: "q0187", topic: "grammar:verbs", level: "A2", difficulty: 3, type: "tiles", q: "Составь разговорный вопрос: «Есть ещё кофе?»", rule: "r0055", words: ["Gibt's", "noch", "Kaffee?"], hint: "Стяжение приклеивается прямо к глаголу.", explain: "Gibt's = gibt es: в вопросе без вопросительного слова глагол стоит первым, и es слипается прямо с ним. Порядок слов при стяжении не меняется – это то же самое Gibt es noch Kaffee?" },
  { id: "q0188", topic: "grammar:verbs", level: "A2", difficulty: 4, type: "mc", q: "Что спрятано в s в сочетании «ins Kino»?", rule: "r0055", opts: ["es", "das", "des", "dies"], ans: 1, hint: "Разверни предлог вместе с артиклем.", explain: "ins = in das, то есть s здесь остаток артикля das, а не местоимения es. Так же устроены ans, aufs, durchs. Местоимение es прячется только там, где оно было подлежащим или дополнением: geht's, gibt's, wenn's." },
  { id: "q0189", topic: "grammar:pronouns", level: "B1", difficulty: 2, type: "mc", q: "Выбери форму: «Ich wasche ___ die Hände.»", rule: "r0056", opts: ["mich", "mir", "sich", "mein"], ans: 1, hint: "Проверь, есть ли рядом второе дополнение.", explain: "die Hände – отдельное Akkusativ-дополнение, оно забирает Akkusativ себе, и возвратному местоимению остаётся Dativ: mir. Без этого дополнения было бы Ich wasche mich. Форма sich – третье лицо и к ich не подходит." },
  { id: "q0190", topic: "grammar:pronouns", level: "B1", difficulty: 3, type: "fill", q: "Впиши возвратное местоимение: «Ich kaufe ___ ein Auto.»", rule: "r0056", ans: "mir", altAns: ["mir", "Mir"], hint: "Кто или что уже занял Akkusativ в этом предложении?", explain: "Akkusativ занят словами ein Auto, поэтому возвратному местоимению остаётся Dativ: mir. Вариант mich означал бы, что я покупаю самого себя." },
  { id: "q0191", topic: "grammar:pronouns", level: "B1", difficulty: 3, type: "mc", q: "Выбери форму: «Ich freue ___, dass du kommst.»", rule: "r0056", opts: ["mir", "mich", "sich", "uns"], ans: 1, hint: "sich freuen – глагол с намертво закреплённым падежом.", explain: "У sich freuen возвратное местоимение всегда в Akkusativ, поэтому mich. Придаточное с dass у таких глаголов на падеж не влияет – mir тут невозможно. Форма uns подошла бы к wir, а sich – к er или sie." },
  { id: "q0192", topic: "grammar:pronouns", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Я желаю себе, чтобы ты пришёл.»", rule: "r0056", words: ["Ich", "wünsche", "mir,", "dass", "du", "kommst."], hint: "Придаточное здесь встаёт на место дополнения.", explain: "У sich wünschen придаточное с dass занимает место прямого дополнения, значит Akkusativ занят и возвратное местоимение уходит в Dativ: mir. В самом придаточном спрягаемый глагол kommst стоит на последнем месте." },
  { id: "q0193", topic: "grammar:wfragen", level: "B1", difficulty: 2, type: "mc", q: "«Ich warte auf meinen Kollegen.» Как спросить «Кого ты ждёшь?»", rule: "r0063", opts: ["Auf wen wartest du?", "Auf wem wartest du?", "Wen wartest du?", "Worauf wartest du?"], ans: 0, hint: "Предлог закреплён за глаголом и в вопросе идёт впереди.", explain: "warten auf управляет Akkusativ, поэтому предлог тянет за собой wen и встаёт перед ним. Auf wem – дательный, у этой пары его нет; без предлога вопрос теряет управление глагола; worauf спрашивает о вещи, а Kollege – человек." },
  { id: "q0194", topic: "grammar:wfragen", level: "B1", difficulty: 3, type: "fill", q: "Впиши вопросительное слово: «Mit ___ sprechen Sie? – Ich spreche mit der Lehrerin.»", rule: "r0063", ans: "wem", altAns: ["wem", "Wem"], hint: "Предлог mit однопадежный, выбора у него нет.", explain: "sprechen mit требует Dativ, потому что mit всегда идёт с Dativ, и этот падеж переходит на вопросительное слово: Mit wem. Форма wen – Akkusativ, после mit она невозможна." },
  { id: "q0195", topic: "grammar:wfragen", level: "B1", difficulty: 3, type: "tiles", q: "Собери вопрос к ответу «Wir sprechen über den Chef.»", rule: "r0063", words: ["Über", "wen", "sprecht", "ihr?"], hint: "Начни с предлога: он не отрывается от глагола.", explain: "sprechen über идёт с Akkusativ, поэтому предлог über стоит первым и тянет за собой wen, а дальше спрягаемый глагол sprecht и подлежащее ihr. Вариант без предлога ломает управление глагола." },
  { id: "q0196", topic: "grammar:wfragen", level: "B1", difficulty: 4, type: "mc", q: "В каком вопросе падеж после предлога выбран неверно?", rule: "r0063", opts: ["Mit wem sprechen Sie?", "Über wen sprecht ihr?", "Auf wem wartest du?", "Von wem hast du das gehört?"], ans: 2, hint: "Проверь, какой падеж закреплён за парой «глагол + предлог».", explain: "warten auf идёт с Akkusativ, поэтому нужно Auf wen, а не Auf wem. В остальных всё сходится: mit и von всегда требуют Dativ (wem), а sprechen über – Akkusativ (wen)." },
  { id: "q0197", topic: "grammar:wfragen", level: "B1", difficulty: 2, type: "mc", q: "Как спросить «Чем ты пишешь?»", rule: "r0064", opts: ["Womit schreibst du?", "Wormit schreibst du?", "Wofür schreibst du?", "Mit wem schreibst du?"], ans: 0, hint: "Посмотри на первую букву предлога mit.", explain: "Вопрос о вещи – это wo плюс предлог, а mit начинается с согласной, поэтому -r- не вставляется: womit. Wofür построено от другого предлога и спрашивает о цели, а Mit wem спрашивает о человеке, а не об инструменте." },
  { id: "q0198", topic: "grammar:wfragen", level: "B1", difficulty: 3, type: "fill", q: "Впиши ответ одним словом: «Worüber sprecht ihr? – Wir sprechen ___.»", rule: "r0064", ans: "darüber", altAns: ["darüber", "Darüber", "darueber", "Darueber"], hint: "Ответ собирается как da плюс тот же предлог.", explain: "В ответе wo- меняется на da-, а предлог остаётся прежним; über начинается с гласной, поэтому вставляется -r-: darüber. Сказать «über es» нельзя – с вещами предлог не соединяется с личным местоимением." },
  { id: "q0199", topic: "grammar:wfragen", level: "B1", difficulty: 3, type: "tiles", q: "Собери вопрос «Чем ты интересуешься?»", rule: "r0064", words: ["Wofür", "interessierst", "du", "dich?"], hint: "У глагола sich interessieren предлог für слипается с wo-.", explain: "Предлог für начинается с согласной, поэтому -r- не нужно: wofür. Дальше идёт спрягаемый глагол interessierst, затем подлежащее du и возвратное dich в конце." },
  { id: "q0200", topic: "grammar:wfragen", level: "B1", difficulty: 4, type: "mc", q: "«Ich warte auf meinen Kollegen.» Чем заменить «auf meinen Kollegen»?", rule: "r0064", opts: ["auf ihn", "darauf", "worauf", "auf es"], ans: 0, hint: "Речь о человеке, а не о вещи.", explain: "Формы da(r)- заменяют вещи и ситуации, а о человеке говорят предлог с личным местоимением: auf ihn. darauf подошло бы только для вещи, worauf – это вопрос, а «auf es» не употребляется вовсе." },
  { id: "q0201", topic: "grammar:verbs", level: "B1", difficulty: 2, type: "tiles", q: "Составь: «Я прочитаю эту книгу.»", rule: "r0065", words: ["Ich", "werde", "das", "Buch", "lesen."], hint: "Спрягается только werden, смысловой глагол – в инфинитиве.", explain: "werden спрягается и занимает второе место, а смысловой глагол в инфинитиве уезжает в самый конец: Ich werde das Buch lesen. Если поставить lesen сразу после werden, рамка развалится и конец предложения останется пустым." },
  { id: "q0202", topic: "grammar:verbs", level: "B1", difficulty: 3, type: "fill", q: "Впиши форму werden: «Wir ___ im Sommer nach Berlin fahren.»", rule: "r0065", ans: "werden", altAns: ["werden", "Werden"], hint: "Смотри на подлежащее wir.", explain: "В Futur I по лицу спрягается только werden, и для wir это форма werden, а смысловой глагол остаётся инфинитивом fahren в конце. Форма wird относится к er/sie/es и с wir не сочетается." },
  { id: "q0203", topic: "grammar:verbs", level: "B1", difficulty: 3, type: "mc", q: "Что означает «Er wird wohl krank sein.»?", rule: "r0065", opts: ["Он, наверное, болен сейчас", "Он обязательно заболеет", "Он болел раньше", "Он скоро выздоровеет"], ans: 0, hint: "Обрати внимание на слово wohl.", explain: "Со словами wohl, wahrscheinlich, sicher конструкция werden плюс инфинитив читается не как будущее, а как догадка о настоящем: речь про сейчас. Значение «заболеет» было бы обычным Futur I без wohl." },
  { id: "q0204", topic: "grammar:verbs", level: "B1", difficulty: 4, type: "mc", q: "В каком предложении Futur II?", rule: "r0065", opts: ["Ich werde das Buch lesen.", "Ich werde das Buch gelesen haben.", "Das Buch wird gelesen.", "Das Buch wird gelesen werden."], ans: 1, hint: "Смотри на самый конец конструкции, а не на слово после werden.", explain: "Futur II – это werden плюс Partizip II плюс haben или sein, и узнаётся по haben в конце. С одним инфинитивом lesen это Futur I, Partizip II без haben/sein даёт Passiv, а werden в конце – Futur I Passiv." },
  { id: "q0205", topic: "grammar:verbs", level: "B1", difficulty: 3, type: "mc", q: "«Der Mechaniker montiert den Motor.» Как то же самое звучит в Passiv?", rule: "r0066", opts: ["Der Motor wird montiert.", "Den Motor wird montiert.", "Der Motor wird montieren.", "Der Motor montiert wird."], ans: 0, hint: "Дополнение в Akkusativ становится подлежащим.", explain: "den Motor было Akkusativ-дополнением, в Passiv оно занимает место подлежащего и переходит в Nominativ – der Motor. Вариант с Den Motor оставляет Akkusativ, и у предложения не остаётся подлежащего, а wird montieren – это werden + инфинитив, то есть будущее время." },
  { id: "q0206", topic: "grammar:verbs", level: "B1", difficulty: 3, type: "fill", q: "Вставь недостающую форму: «Der Motor ist montiert ___.» – Мотор смонтировали.", rule: "r0066", ans: "worden", altAns: ["worden", "Worden"], hint: "В Passiv у причастия от werden отпадает приставка ge-.", explain: "Perfekt Passiv строится как sein + Partizip II смыслового глагола + worden, и приставка ge- здесь отпадает. Форма geworden осталась бы только у обычного глагола «становиться»: Ich bin Arzt geworden." },
  { id: "q0207", topic: "grammar:verbs", level: "B1", difficulty: 4, type: "mc", q: "«Man hilft dem Kind.» Как это выглядит в Passiv?", rule: "r0066", opts: ["Dem Kind wird geholfen.", "Das Kind wird geholfen.", "Der Kind wird geholfen.", "Dem Kind werden geholfen."], ans: 0, hint: "Проверь, какой падеж требует helfen.", explain: "helfen управляет Dativ, а подлежащим в Passiv становится только Akkusativ-дополнение, поэтому dem Kind падеж сохраняет и подлежащего в предложении просто нет. Раз подлежащего нет, werden стоит в форме wird." },
  { id: "q0208", topic: "grammar:verbs", level: "B1", difficulty: 2, type: "fill", q: "Поставь «Der Motor wird montiert.» в Präteritum: «Der Motor ___ montiert.»", rule: "r0066", ans: "wurde", altAns: ["wurde", "Wurde"], hint: "Время показывает только форма werden.", explain: "Залог держит Partizip II на конце, а время задаёт спрягаемое werden, поэтому в прошедшем оно принимает форму wurde. Поставили бы war – получилось бы sein + Partizip II, то есть готовый результат, а не идущий монтаж." },
  { id: "q0209", topic: "grammar:verbs", level: "B1", difficulty: 3, type: "tiles", q: "Составь: «Мотор монтирует механик» – назови деятеля через von.", rule: "r0066", words: ["Der", "Motor", "wird", "von", "dem", "Mechaniker", "montiert."], hint: "Деятель вводится предлогом von с Dativ.", explain: "Подлежащее Passiv – der Motor, спрягаемое wird стоит вторым, а Partizip II уходит в самый конец. Деятель добавляется как von + Dativ и встаёт внутрь рамки, между wird и montiert." },
  { id: "q0210", topic: "grammar:verbs", level: "B1", difficulty: 3, type: "mc", q: "«Die Wäsche ___ gewaschen.» – бельё выстирано, работа уже закончена. Что вставить?", rule: "r0066", opts: ["ist", "wird", "wurde", "hat"], ans: 0, hint: "Процесс или результат?", explain: "sein + Partizip II описывает готовый результат, поэтому здесь ist. С wird или wurde вышел бы Passiv-процесс – бельё стирают или стирали прямо в тот момент, а hat + Partizip II дало бы Perfekt в Aktiv и потребовало бы назвать того, кто стирал." },
  { id: "q0211", topic: "grammar:wordorder", level: "B2", difficulty: 3, type: "mc", q: "Перепиши «Wenn keine Lösung gefunden wird, muss ich kündigen» без wenn и мягче. Какой вариант верный?", rule: "r0067", opts: ["Sollte keine Lösung gefunden werden, müsste ich kündigen.", "Sollte keine Lösung gefunden werden, ich müsste kündigen.", "Keine Lösung sollte gefunden werden, müsste ich kündigen.", "Sollte keine Lösung werden gefunden, müsste ich kündigen."], ans: 0, hint: "Работу wenn берёт на себя место глагола.", explain: "Убрали wenn – значит условие обозначает сам спрягаемый глагол, переехавший на первое место, а остаток придаточного сохраняет порядок gefunden werden. В главной части придаточное занимает первую позицию, поэтому müsste идёт сразу за запятой, а подлежащее ich – после него." },
  { id: "q0212", topic: "grammar:wordorder", level: "B2", difficulty: 3, type: "tiles", q: "Собери вежливую фразу из письма: «Если у вас возникнут вопросы, обращайтесь.»", rule: "r0067", words: ["Sollten", "Sie", "Fragen", "haben,", "melden", "Sie", "sich", "gern."], hint: "Начни со спрягаемого глагола.", explain: "Условие без wenn открывается спрягаемым sollten, согласованным с Sie, а инфинитив haben уезжает в конец придаточного. После запятой идёт главная часть в императиве: melden Sie sich gern." },
  { id: "q0213", topic: "grammar:wordorder", level: "B2", difficulty: 3, type: "fill", q: "Допиши главную часть: «Sollte es regnen, ___ wir zu Hause.» – Если вдруг пойдёт дождь, останемся дома.", rule: "r0067", ans: "bleiben", altAns: ["bleiben", "Bleiben"], hint: "Придаточное уже занимает первое место.", explain: "Условное предложение целиком стоит на первой позиции, поэтому спрягаемый глагол главной части идёт сразу за запятой, а подлежащее wir – только после него. Порядок «wir bleiben» отодвинул бы глагол на третье место и сломал бы рамку." },
  { id: "q0214", topic: "grammar:wordorder", level: "B2", difficulty: 3, type: "mc", q: "Письмо должно звучать мягко, без ультиматума: «Sollte keine Lösung gefunden werden, ___ ich den Vertrag kündigen.»", rule: "r0067", opts: ["müsste", "muss", "müssten", "müsst"], ans: 0, hint: "Чем дальше форма от факта, тем мягче звучит.", explain: "Konjunktiv II müsste переводит следствие в область возможного – «мне пришлось бы расторгнуть», и у адресата остаётся выход. Индикатив muss звучит как ультиматум, а müssten и müsst не согласуются с подлежащим ich." },
  { id: "q0215", topic: "grammar:wordorder", level: "B2", difficulty: 3, type: "fill", q: "Допиши начало: «___ ich mehr Zeit, würde ich helfen.» – Будь у меня больше времени, я бы помог.", rule: "r0067", ans: "Hätte", altAns: ["Hätte", "hätte", "Haette", "haette"], hint: "Союза нет – условие держится на позиции глагола.", explain: "Без союза условие опознаётся только по тому, что спрягаемый глагол в Konjunktiv II вышел на первое место, а подлежащее ich встало за ним. Порядок «Ich hätte mehr Zeit» дал бы обычное утверждение, а не условие." },
  { id: "q0216", topic: "grammar:wordorder", level: "B2", difficulty: 4, type: "mc", q: "В письме клиенту нельзя указывать пальцем на адресата. Какое условие этому отвечает?", rule: "r0067", opts: ["Sollte keine Lösung gefunden werden", "Sollten Sie keine Lösung finden", "Wenn Sie keine Lösung finden", "Sie sollten eine Lösung finden"], ans: 0, hint: "Кто в предложении назван деятелем?", explain: "В gefunden werden стоит пассив без деятеля, поэтому неудача ни на кого не записывается. Остальные варианты делают Sie подлежащим и прямо адресуют её собеседнику, а последний вдобавок читается как совет-требование, а не как условие." },
  { id: "q0217", topic: "grammar:adjectives", level: "A1", difficulty: 2, type: "mc", q: "В каком случае прилагательное остаётся без окончания?", rule: "r0019", opts: ["после sein, werden, bleiben", "перед существительным в Nominativ", "перед существительным в Akkusativ", "после определённого артикля der/die/das"], ans: 0, hint: "Сравни: Das Haus ist groß и ein großes Haus.", explain: "Окончание нужно только тогда, когда прилагательное стоит перед существительным и должно показать его род, число и падеж: der gesunde Mann, ein großes Haus. После sein, werden, bleiben прилагательное стоит отдельно, согласовывать не с чем, и оно остаётся в словарной форме: Das Haus ist groß." },
  { id: "q0218", topic: "grammar:wordorder", level: "A1", difficulty: 2, type: "mc", q: "Какое место занимает спрягаемый глагол в придаточном с weil?", rule: "r0023", opts: ["последнее", "второе", "первое", "сразу после weil"], ans: 0, hint: "Сравни: Ich bin krank и …, weil ich krank bin.", explain: "weil – подчинительный союз: он вводит Nebensatz, а в Nebensatz рамку закрывает спрягаемый глагол, и тот уезжает в самый конец. Второе место – это порядок главного предложения, а сразу за союзом спрягаемый глагол не ставится никогда, там идёт подлежащее." },
  { id: "q0219", topic: "grammar:cases", level: "A1", difficulty: 2, type: "mc", q: "Какой падеж обозначает прямой объект – того, на кого или на что направлено действие?", rule: "r0024", opts: ["Nominativ", "Akkusativ", "Dativ", "Genitiv"], ans: 1, hint: "Задай к слову вопрос: кого? что?", explain: "Прямой объект отвечает на вопрос Wen? Was? и стоит в Akkusativ: Ich kaufe einen Kaffee. Nominativ – это подлежащее, тот, кто действует, а Dativ – адресат, отвечающий на Wem?: Ich gebe dir das Buch." },
  { id: "q0220", topic: "grammar:cases", level: "A2", difficulty: 2, type: "mc", q: "После какого из этих глаголов лицо стоит НЕ в Dativ, а в Akkusativ?", rule: "r0025", opts: ["helfen", "danken", "fragen", "gefallen"], ans: 2, hint: "Проверь каждый глагол вопросом «Wem?».", explain: "helfen, danken и gefallen входят в список дативных глаголов: к лицу после них задают вопрос «Wem?» (Ich helfe dir, Das gefällt mir). Глагол fragen в этот список не входит и управляет Akkusativ: Ich frage dich." },
  { id: "q0221", topic: "grammar:cases", level: "A2", difficulty: 2, type: "mc", q: "Одно дополнение – существительное, другое – личное местоимение. Что из них стоит первым?", rule: "r0026", opts: ["существительное", "местоимение", "всегда Dativ", "всегда Akkusativ"], ans: 1, hint: "Падеж здесь не решает.", explain: "Личное местоимение всегда притягивается вперёд существительного, независимо от падежа: Ich gebe ihm das Buch (Dativ впереди), но и Ich gebe es dem Mann (Akkusativ впереди). Поэтому ответы «всегда Dativ» и «всегда Akkusativ» неверны – порядок задаёт не падеж, а местоимение." },
  { id: "q0222", topic: "grammar:cases", level: "A2", difficulty: 2, type: "mc", q: "В предложении «Er schenkt der Frau einen Ring» на какой вопрос отвечает «einen Ring»?", rule: "r0027", opts: ["Wer?", "Wem?", "Was?", "Wessen?"], ans: 2, hint: "Определи роль каждого члена предложения.", explain: "einen Ring – это подарок, сам предмет: он стоит в Akkusativ и отвечает на вопрос «Was?». На «Wem?» отвечает der Frau (адресат в Dativ), на «Wer?» – подлежащее er в Nominativ." },
  { id: "q0223", topic: "grammar:cases", level: "A1", difficulty: 2, type: "mc", q: "На какой вопрос отвечает дополнение в Dativ?", rule: "r0028", opts: ["Wer?", "Wen?", "Wem?", "Wessen?"], ans: 2, hint: "Dativ – это косвенный объект.", explain: "Dativ – косвенный объект, и проверяется он вопросом Wem? (Ich helfe der Frau – кому?). Wer? спрашивает о подлежащем и даёт Nominativ, Wen? относится к прямому объекту и даёт Akkusativ, Wessen? – вопрос Genitiv." },
  { id: "q0224", topic: "grammar:cases", level: "A2", difficulty: 2, type: "mc", q: "Какое из этих слов вводит Nebensatz и отправляет спрягаемый глагол в конец?", rule: "r0029", opts: ["und", "aber", "obwohl", "oder"], ans: 2, hint: "Подчинительный союз против сочинительных.", explain: "obwohl – подчинительный союз: он открывает придаточное, и спрягаемый глагол уходит на последнее место (Er kommt, obwohl er krank ist). und, aber и oder – сочинительные: они лишь соединяют предложения и порядок слов внутри них не трогают." },
  { id: "q0225", topic: "grammar:cases", level: "A1", difficulty: 2, type: "mc", q: "Из каких двух слов состоит форма am?", rule: "r0030", opts: ["an + der", "an + dem", "an + das", "an + den"], ans: 1, hint: "Слияние работает только с одним артиклем.", explain: "am – это сращение предлога an с артиклем Dativ dem, поэтому am возможно только у мужского и среднего рода и только при вопросе Wo?. an + das даёт другую форму – ans, а с der слияния нет вообще: an der Wand." },
  { id: "q0226", topic: "grammar:cases", level: "A1", difficulty: 2, type: "mc", q: "Что решает, в каком падеже стоит существительное после предлогов auf, in, an, unter, über?", rule: "r0031", opts: ["род существительного", "вопрос Wo? или Wohin?", "число существительного", "место предлога в предложении"], ans: 1, hint: "Эти девять предлогов недаром зовут Wechselpräpositionen.", explain: "У этих девяти предлогов падеж переключает вопрос: Wo? (положение) → Dativ, Wohin? (движение) → Akkusativ. Род и число задают лишь форму артикля внутри уже выбранного падежа. У zu или nach падеж закреплён самим предлогом, и вопрос ничего не меняет." },
  { id: "q0227", topic: "grammar:verbs", level: "A2", difficulty: 2, type: "mc", q: "Что именно заменяет апостроф в стяжениях вроде geht's или wenn's?", rule: "r0055", opts: ["выпавшую букву e", "всё местоимение es", "букву s", "пробел между словами"], ans: 0, hint: "Сравни полную форму dass es с её стяжением.", explain: "Апостроф ставится на месте пропавшей e, а s остаётся как остаток es: dass es → dass's. Если бы апостроф заменял всё местоимение, буквы s в слове вообще не было бы. У частых сращений апостроф часто вовсе не пишут: gehts, wenns." },
  { id: "q0228", topic: "grammar:pronouns", level: "B1", difficulty: 2, type: "mc", q: "От чего зависит падеж возвратного местоимения у глаголов вроде waschen, kaufen, wünschen?", rule: "r0056", opts: ["от лица подлежащего", "от наличия рядом отдельного Akkusativ-дополнения", "от времени глагола", "от места местоимения в предложении"], ans: 1, hint: "Сравни: Ich wasche mich и Ich wasche mir die Hände.", explain: "Такие глаголы умеют брать отдельное Akkusativ-дополнение: появилось die Hände или ein Auto – Akkusativ занят, и возвратному остаётся Dativ (mir); дополнения нет – возвратное само стоит в Akkusativ (mich). У глаголов вроде sich freuen падеж закреплён за глаголом и не меняется ни от чего." },
  { id: "q0229", topic: "grammar:wfragen", level: "B1", difficulty: 2, type: "mc", q: "Глагол warten auf управляет Akkusativ. Какое слово ставится после предлога в вопросе о человеке?", rule: "r0063", opts: ["wen", "wem", "wer", "was"], ans: 0, hint: "Падеж приходит от связки «глагол + предлог».", explain: "Akkusativ от wer – это wen, поэтому вопрос звучит Auf wen wartest du? wem – Dativ и нужен другим парам (sprechen mit – Mit wem), wer – Nominativ и после предлога стоять не может, а was спрашивает о вещи и сливается с предлогом в одно слово (worauf)." },
  { id: "q0230", topic: "grammar:wfragen", level: "B1", difficulty: 2, type: "mc", q: "От чего зависит, появится ли -r- в формах wo(r)- и da(r)-?", rule: "r0064", opts: ["от первой буквы предлога", "от падежа, которого требует глагол", "от рода существительного", "от того, вопрос это или ответ"], ans: 0, hint: "Произнеси форму без -r- и послушай, выговаривается ли она.", explain: "-r- вставляется, когда предлог начинается с гласной: an, auf, über дают woran, worauf, worüber и daran, darauf, darüber. Перед согласной его нет: mit, von, für дают womit, wovon, wofür. Падеж, род и то, вопрос это или ответ, на вставку не влияют." },
  { id: "q0231", topic: "grammar:verbs", level: "B1", difficulty: 2, type: "mc", q: "В какой форме и на каком месте стоит смысловой глагол в Futur I?", rule: "r0065", opts: ["в инфинитиве в конце предложения", "в инфинитиве сразу после werden", "в Partizip II в конце предложения", "спрягается по лицу на втором месте"], ans: 0, hint: "Спрягается только вспомогательный глагол.", explain: "werden спрягается и стоит вторым, а смысл лежит в глаголе на конце, и он остаётся инфинитивом: Ich werde das Buch lesen. Partizip II в конце – это уже Passiv или, вместе с haben/sein, Futur II; по лицу в такой конструкции меняется только werden." },
  { id: "q0232", topic: "grammar:verbs", level: "B1", difficulty: 2, type: "mc", q: "Из чего складывается форма Passiv в немецком?", rule: "r0066", opts: ["sein + Partizip II", "werden + Partizip II", "werden + инфинитив", "haben + Partizip II"], ans: 1, hint: "Одна часть отвечает за время, другая – за залог.", explain: "Passiv – это werden + Partizip II: спрягаемое werden несёт время и лицо, а Partizip II в конце показывает, что подлежащее получает действие. werden + инфинитив – это будущее время, sein + Partizip II – готовый результат, а haben + Partizip II – обычный Perfekt в Aktiv." },
  { id: "q0233", topic: "grammar:wordorder", level: "B2", difficulty: 2, type: "mc", q: "Если союз wenn убран, что показывает, что перед нами всё-таки условие?", rule: "r0067", opts: ["спрягаемый глагол стоит на первом месте", "спрягаемый глагол стоит в конце придаточного", "запятая между частями", "Konjunktiv II в главной части"], ans: 0, hint: "Сравни с обычным повествованием.", explain: "Когда wenn убирают, его работу берёт на себя позиция глагола: спрягаемый глагол выходит на первое место, тогда как в повествовательном предложении там стоит подлежащее или обстоятельство, а глагол вторым. Глагол в конце – признак придаточного с союзом, а запятая и Konjunktiv сами по себе условия не создают." },
  { id: "q0234", topic: "communication:opinion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Я считаю это хорошей идеей.»", words: ["Ich", "finde", "das", "eine", "gute", "Idee."], hint: "finden здесь «считать», а не «находить»", explain: "Оценка после finden стоит в Akkusativ: eine gute Idee. Отрицание строится через kein: Ich finde das keine gute Idee." },
  { id: "q0235", topic: "communication:opinion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Это верно лишь отчасти.»", words: ["Das", "stimmt", "nur", "zum", "Teil."], hint: "stimmen – быть верным", explain: "zum Teil – устойчивое сочетание, zu + dem = zum. Мягкое несогласие: сначала признаёшь часть, потом возражаешь." },
  { id: "q0236", topic: "communication:opinion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Идея мне очень нравится.»", rule: "r0053", words: ["Die", "Idee", "finde", "ich", "super."], hint: "дополнение вперёд – значит инверсия", explain: "Die Idee вынесено на первое место для усиления. Глагол обязан остаться вторым, поэтому подлежащее ich уходит за него." },
  { id: "q0237", topic: "communication:opinion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «С этим я согласен.»", rule: "r0053", words: ["Damit", "bin", "ich", "einverstanden."], hint: "einverstanden sein mit + Dativ", explain: "Damit заменяет mit + это. Стоит первым, значит bin второе, ich после глагола." },
  { id: "q0238", topic: "communication:opinion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Я тоже так считаю.»", rule: "r0053", words: ["Das", "sehe", "ich", "auch", "so."], hint: "дословно «я тоже это так вижу»", explain: "Das вынесено вперёд, отсюда инверсия. sehen здесь не «видеть», а «воспринимать, считать»." },
  { id: "q0239", topic: "communication:discussion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Хочешь что-то добавить?»", words: ["Möchtest", "du", "dazu", "noch", "etwas", "sagen?"], hint: "модальный спрягается, смысловой в конец", explain: "Вопрос без вопросительного слова начинается с глагола. möchtest спрягается, sagen уходит в конец – глагольная рамка." },
  { id: "q0240", topic: "communication:discussion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Как тебе предложение?»", words: ["Wie", "findest", "du", "den", "Vorschlag?"], hint: "finden + Akkusativ", explain: "W-Frage: вопросительное слово, глагол, подлежащее. der Vorschlag в Akkusativ становится den Vorschlag." },
  { id: "q0241", topic: "communication:discussion", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Есть идеи?»", words: ["Hast", "du", "eine", "Idee?"], hint: "Ja/Nein-Frage начинается с глагола", explain: "По-русски множественное «идеи», по-немецки естественнее единственное eine Idee." },
  { id: "q0242", topic: "communication:discussion", level: "A2", difficulty: 4, type: "tiles", q: "Составь: «Что тебе кажется лучше?»", words: ["Was", "findest", "du", "besser?"], hint: "besser – сравнительная от gut", explain: "Форма сравнения стоит без окончания, потому что она не перед существительным, а после глагола." },
  { id: "q0243", topic: "communication:discussion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Извини, можно тебя ненадолго перебить?»", words: ["Entschuldigung,", "kann", "ich", "dich", "mal", "kurz", "unterbrechen?"], hint: "unterbrechen + Akkusativ", explain: "Рамка: kann спрягается, unterbrechen в конец. mal и kurz смягчают просьбу – без них фраза звучит резко." },
  { id: "q0244", topic: "communication:discussion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Момент, можно я сразу скажу по этому поводу?»", words: ["Moment,", "kann", "ich", "dazu", "direkt", "mal", "etwas", "sagen?"], hint: "dazu = «по этому поводу»", explain: "dazu заменяет zu + это. Модальный kann на втором месте, sagen закрывает рамку." },
  { id: "q0245", topic: "communication:discussion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «Секунду, я хочу кое-что добавить.»", words: ["Einen", "Augenblick,", "ich", "möchte", "etwas", "hinzufügen."], hint: "Augenblick стоит в Akkusativ", explain: "Einen Augenblick – усечённое «подожди одно мгновение», отсюда винительный падеж. möchte + hinzufügen – рамка." },
  { id: "q0246", topic: "communication:discussion", level: "B1", difficulty: 4, type: "tiles", q: "Составь: «По этому пункту мне ещё кое-что приходит в голову.»", rule: "r0053", words: ["Zu", "dem", "Punkt", "fällt", "mir", "noch", "etwas", "ein."], hint: "einfallen идёт с Dativ, приставка отделяемая", explain: "Обстоятельство вперёд – инверсия, fällt второе. Приставка ein- уходит в самый конец. Кому приходит в голову – Dativ: mir." },
  { id: "q0247", topic: "communication:opinion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «Я считаю это хорошей идеей.»", ans: "Ich finde das eine gute Idee.", hint: "finden + Akkusativ", explain: "Оценка после finden – в винительном падеже." },
  { id: "q0248", topic: "communication:opinion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «Это верно лишь отчасти.»", ans: "Das stimmt nur zum Teil.", hint: "zu + dem = zum", explain: "Устойчивое сочетание zum Teil, раздельно не пишется." },
  { id: "q0249", topic: "communication:opinion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «Идея мне очень нравится.»", rule: "r0053", ans: "Die Idee finde ich super.", altAns: ["Ich finde die Idee super."], hint: "можно начать и с Die Idee, и с Ich", explain: "Оба порядка верны. С Die Idee впереди появляется инверсия и усиление." },
  { id: "q0250", topic: "communication:opinion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «Но это тоже важно.»", ans: "Es ist aber auch wichtig.", hint: "aber стоит внутри, а не в начале", explain: "aber здесь не союз в начале предложения, а частица на третьем месте – она не влияет на порядок слов." },
  { id: "q0251", topic: "communication:opinion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «С этим я согласен.»", rule: "r0053", ans: "Damit bin ich einverstanden.", altAns: ["Ich bin damit einverstanden."], hint: "einverstanden sein mit + Dativ", explain: "Оба порядка верны. Damit впереди даёт инверсию." },
  { id: "q0252", topic: "communication:opinion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «Я тоже так считаю.»", rule: "r0053", ans: "Das sehe ich auch so.", hint: "дословно «я тоже это так вижу»", explain: "Das на первом месте, отсюда инверсия: глагол второй, подлежащее третье." },
  { id: "q0253", topic: "communication:discussion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «Хочешь что-то добавить?»", ans: "Möchtest du dazu noch etwas sagen?", hint: "модальный впереди, смысловой в конец", explain: "Вопрос без вопросительного слова открывается спрягаемым глаголом." },
  { id: "q0254", topic: "communication:discussion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «Как тебе предложение?»", ans: "Wie findest du den Vorschlag?", hint: "finden + Akkusativ", explain: "der Vorschlag → den Vorschlag." },
  { id: "q0255", topic: "communication:discussion", level: "A2", difficulty: 5, type: "open", q: "Переведи: «Есть идеи?»", ans: "Hast du eine Idee?", hint: "по-немецки единственное число", explain: "Русское множественное «идеи» переводится единственным eine Idee." },
  { id: "q0256", topic: "communication:discussion", level: "A2", difficulty: 5, type: "open", q: "Переведи: «Что думаешь?»", ans: "Was denkst du?", hint: "W-Frage", explain: "Вопросительное слово, глагол, подлежащее." },
  { id: "q0257", topic: "communication:discussion", level: "A2", difficulty: 5, type: "open", q: "Переведи: «Что тебе кажется лучше?»", ans: "Was findest du besser?", hint: "besser без окончания", explain: "Сравнительная форма стоит после глагола, значит окончания не получает." },
  { id: "q0258", topic: "communication:discussion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «Извини, можно тебя ненадолго перебить?»", ans: "Entschuldigung, kann ich dich mal kurz unterbrechen?", hint: "unterbrechen + Akkusativ", explain: "Приставка unter- здесь неотделяемая: unterbrechen, не breche unter." },
  { id: "q0259", topic: "communication:discussion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «Момент, можно я сразу скажу по этому поводу?»", ans: "Moment, kann ich dazu direkt mal etwas sagen?", hint: "dazu = «по этому поводу»", explain: "Модальный kann второй, sagen в конце." },
  { id: "q0260", topic: "communication:discussion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «Секунду, я хочу кое-что добавить.»", ans: "Einen Augenblick, ich möchte etwas hinzufügen.", hint: "Augenblick в Akkusativ", explain: "Усечённое «подожди одно мгновение» – отсюда винительный." },
  { id: "q0261", topic: "communication:discussion", level: "B1", difficulty: 5, type: "open", q: "Переведи: «По этому пункту мне ещё кое-что приходит в голову.»", ans: "Zu dem Punkt fällt mir noch etwas ein.", hint: "einfallen + Dativ, приставка отделяемая", explain: "Кому приходит в голову – Dativ: mir. Приставка ein- в самый конец." },
];

